# دالة للتحقق من توازن الأقواس
def is_balanced(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '({[':
            stack.append(ch)
        elif ch in ')}]':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

# قراءة عدد حالات الاختبار
t = int(input())
for _ in range(t):
    s = input().strip()
    print('YES' if is_balanced(s) else 'NO')
