import sys

def subset_sum_exists(nums, K):
    dp = [0] * (K + 1)
    dp[0] = 1
    for x in nums:
        if x > K:
            continue
        for s in range(K - x, -1, -1):
            if dp[s]:
                dp[s + x] = 1
        if dp[K]:
            break
    return dp[K]

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        K = int(next(it))
        nums = [int(next(it)) for _ in range(N)]
        out_lines.append('1' if subset_sum_exists(nums, K) else '0')
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    main()
```
هذا الكود يقرأ جميع البيانات مرة واحدة لتسريع الإدخال، يستخدم دالة منفصلة لتوضيح الفكرة، ويطبع 1 إذا وجد مجموعة فرعية مجموعها K وإلا 0.

