#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<pair<int,int>> edges(m);
    vector<vector<int>> adj(n);
    vector<int> deg(n, 0);
    for (int i = 0; i < m; ++i) {
        int x, y; cin >> x >> y; --x; --y;
        edges[i] = {x, y};
        adj[x].push_back(y);
        adj[y].push_back(x);
        ++deg[x]; ++deg[y];
    }

    // حالة الإزالة: false يعني مازال موجوداً، true يعني تم حذفه من الـ k‑core
    vector<char> removed(n, false);
    queue<int> q;
    int alive = n;
    // حذف الرؤوس التي درجتها أقل من k في الرسم الكامل
    for (int i = 0; i < n; ++i) {
        if (deg[i] < k && !removed[i]) {
            q.push(i);
            removed[i] = true;
            --alive;
        }
    }
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (int to : adj[v]) {
            if (removed[to]) continue;
            if (--deg[to] < k) {
                removed[to] = true;
                q.push(to);
                --alive;
            }
        }
    }

    vector<int> answer; // سيحمل الإجابات من اليوم الأخير إلى الأول
    answer.reserve(m);
    answer.push_back(alive); // بعد إضافة كل الحواف (اليوم m)

    // نعيد الحواف بالعكس، نزيل كل حافة واحدةً تلو الأخرى
    for (int i = m-1; i > 0; --i) { // نبدأ من الحافة التي أضيفت في اليوم i+1
        auto [a, b] = edges[i];
        // حذف الحافة من القوائم (نقلل الدرجة إذا كان الطرفان ما زالا غير محذوفين)
        if (!removed[a] && !removed[b]) {
            if (--deg[a] < k) {
                removed[a] = true;
                q.push(a);
                --alive;
            }
            if (--deg[b] < k) {
                removed[b] = true;
                q.push(b);
                --alive;
            }
            // معالجة السلسلة المتتالية من الإزالات
            while (!q.empty()) {
                int v = q.front(); q.pop();
                for (int to : adj[v]) {
                    if (removed[to]) continue;
                    if (--deg[to] < k) {
                        removed[to] = true;
                        q.push(to);
                        --alive;
                    }
                }
            }
        } else {
            // إذا كان أحد الطرفين محذوفاً، نحتاج فقط لتقليل الدرجة للطرف الآخر إذا لم يكن محذوفاً
            if (!removed[a] && removed[b]) {
                if (--deg[a] < k) {
                    removed[a] = true;
                    q.push(a);
                    --alive;
                }
            } else if (!removed[b] && removed[a]) {
                if (--deg[b] < k) {
                    removed[b] = true;
                    q.push(b);
                    --alive;
                }
            }
            while (!q.empty()) {
                int v = q.front(); q.pop();
                for (int to : adj[v]) {
                    if (removed[to]) continue;
                    if (--deg[to] < k) {
                        removed[to] = true;
                        q.push(to);
                        --alive;
                    }
                }
            }
        }
        answer.push_back(alive);
    }

    // طباعة الإجابات من اليوم الأول إلى الأخير
    for (int i = (int)answer.size() - 1; i >= 0; --i) {
