مسألة جديدة: اكتب دالة تستعيد التبديلة من مصفوفة s باستخدام شجرة فِنْك بسيطة.
```cpp
#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<long long> bit; // يخزن القيم (الأعداد نفسها)
    BIT(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        bit.assign(n + 2, 0);
    }
    // إضافة val إلى الموضع idx
    void add(int idx, long long val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    // مجموع القيم من 1 إلى idx
    long long sum(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    // إيجاد أصغر موضع بحيث يكون المجموع التراكمي >= k (k ≥ 1)
    int kth(long long k) const {
        int idx = 0;
        int mask = 1;
        while (mask << 1 <= n) mask <<= 1; // أعلى قوة 2 ≤ n
        for (int step = mask; step; step >>= 1) {
            int nxt = idx + step;
            if (nxt <= n && bit[nxt] < k) {
                idx = nxt;
                k -= bit[nxt];
            }
        }
        return idx + 1; // الموضع المطلوب
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<long long> s(n);
    for (int i = 0; i < n; ++i) cin >> s[i];

    BIT ft(n);
    // ملء الشجرة: القيمة i في الموضع i
    for (int i = 1; i <= n; ++i) ft.add(i, i);

    vector<int> p(n);
    // المعالجة من اليمين إلى اليسار
    for (int i = n - 1; i >= 0; --i) {
        long long need = s[i] + 1; // نحتاج إلى أول موضع يصبح فيه المجموع ≥ s_i+1
        int pos = ft.kth(need);
        p[i] = pos;
        ft.add(pos, -pos); // حذف العنصر من الشجرة
    }

