// إرجاع قيمة الموضع pos (1‑مؤشر) في الدورة الإيلرية الصغرى المعجمية
long long getVertex(long long n, long long pos) {
    if (pos == n * (n - 1) + 1) return 1; // العنصر الأخير هو 1 دائماً
    long long i = 1; // بداية الكتلة
    while (true) {
        long long blockSize = 2 * (n - i); // حجم كتلة i
        if (pos > blockSize) {
            pos -= blockSize; // تخطي الكتلة بالكامل
            ++i;
        } else {
            // داخل كتلة i
            if (pos % 2 == 1) {
                // موضع فردي داخل الكتلة: هو i نفسه
                return i;
            } else {
                // موضع زوجي: يمثل الوجهة j
                long long offset = pos / 2; // عدد أزواج مكتملة قبل هذا الموضع
                return i + offset; // j = i + offset
            }
        }
    }
}

int main() {
