#include <bits/stdc++.h>
using namespace std;

struct State {
    long long val;   // القيمة القصوى
    int prev;        // عدد الوحدات المختارة قبل هذه الوحدة
    bool take;       // هل أخذنا هذه الوحدة أم لا
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;cin>>T;
    while(T--){
        int n,k;cin>>n>>k;
        vector<long long>a(n+1),b(n+1);
        for(int i=1;i<=n;i++)cin>>a[i]>>b[i];
        // dp[i][c] = أقصى مجموع باستخدام أول i وحدة واختيار c وحدة
        vector<vector<State>> dp(n+1, vector<State>(k+1,{-4e18,-1,false}));
        dp[0][0].val=0;
        for(int i=1;i<=n;i++){
            for(int c=0;c<=k;c++){
                // لا نأخذ الوحدة i
                if(dp[i-1][c].val>dp[i][c].val){
                    dp[i][c]=dp[i-1][c];
                    dp[i][c].take=false;
                }
                // نأخذ الوحدة i إذا كان لدينا مكان
                if(c>0 && dp[i-1][c-1].val!=-4e18){
                    // القوة التي ستحصل عليها الوحدة i إذا كانت في الموضع c
                    long long add = a[i] + b[i]*(c-1);
                    long long cand = dp[i-1][c-1].val + add;
                    if(cand>dp[i][c].val){
                        dp[i][c].val=cand;
                        dp[i][c].prev=c-1;
                        dp[i][c].take=true;
                    }
                }
            }
        }
        // نختار أفضل قيمة بين جميع c≤k (يمكن أن نختار أقل من k إذا كان ذلك أفضل)
        int bestC=0; long long bestVal=dp[n][0].val;
        for(int c=1;c<=k;c++) if(dp[n][c].val>bestVal){bestVal=dp[n][c].val;bestC=c;}
        // استرجاع الوحدات المختارة
        vector<int> chosen;
        int i=n, c=bestC;
        while(i>0){
            if(dp[i][c].take){
                chosen.push_back(i);
                c--;
            }
            i--;
        }
        reverse(chosen.begin(),chosen.end()); // الآن في ترتيب الاستدعاء حسب الفهرس الأصلي
        // نحتاج لترتيبهم حسب b تصاعديًا داخل المجموعة المختارة
        sort(chosen.begin(),chosen.end(),[&](int x,int y){return b[x]<b[y];});
        // الآن نكوّن قائمة الأفعال
        vector<int> actions;
        vector<int> alive; // الوحدات الحالية في الجيش
        for(int idx:chosen){
            actions.push_back(idx); // استدعاء
            alive.push_back(idx);
            if((int)alive.size()>k){ // إذا تجاوزنا الحد، نحذف أضعف وحدة (أول وحدة تم استدعاؤها)
                int rem = alive.front();
                actions.push_back(-rem);
                alive.erase(alive.begin());
            }
        }
        // قد يبقى عدد الوحدات أقل من k، لا مشكلة.
        cout<<actions.size()<<"\n";
        for(size_t p=0;p<actions.size();p++){
            if(p) cout<<' ';
            cout<<actions[p];
        }
        cout<<"\n";
    }
    return 0;
}
```
هذا البرنامج يقرأ جميع الحالات، يستخدم DP لاختيار أفضل مجموعة من ≤k منيون، ثم يرتبهم حسب قيمة b لتطبيق الزيادة بأفضل طريقة، وأخيرًا يولّد تسلسل الاستدعاءات والتدميرات بحيث لا يتجاوز عدد الوحدات في أي لحظة k. البرنامج مكتوب بلغة C++17 ويتوافق مع قيود المسألة.

