#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if(!(cin >> n >> k)) return 0;
    vector<int> a(n+1);
    for(int i=1;i<=n;i++) cin >> a[i];

    // عدّ تكرارات القيم داخل النافذة الحالية
    vector<int> freq(n+1,0);
    // عدد القيم التي تظهر مرة واحدة حالياً
    int uniq_once = 0;
    // مؤشر بداية النافذة
    int left = 1;
    // dp و prefix_sum
    vector<int> dp(n+1,0), pref(n+1,0);
    dp[0] = 1;
    pref[0] = 1;

    for(int right=1; right<=n; ++right){
        // أضف العنصر right إلى النافذة
        int val = a[right];
        if(freq[val]==0) uniq_once++;          // يصبح يظهر مرة واحدة
        else if(freq[val]==1) uniq_once--;    // يصبح يظهر أكثر من مرة
        freq[val]++;

        // حرّك left حتى يصبح عدد القيم التي تظهر مرة واحدة ≤ k
        while(uniq_once > k){
            int v = a[left];
            if(freq[v]==1) uniq_once--;        // سيختفي تماماً
            else if(freq[v]==2) uniq_once++;  // سيعود للظهور مرة واحدة
            freq[v]--;
            ++left;
        }
        // الآن كل i في [left .. right] تجعل القطعة [i..right] صالحة
        // مجموع dp[i-1] لهذا النطاق هو pref[right-1] - pref[left-2]
        int sum = pref[right-1];
        if(left-2 >= 0) sum = (sum - pref[left-2] + MOD) % MOD;
        dp[right] = sum;
        pref[right] = (pref[right-1] + dp[right]) % MOD;
    }

    cout << dp[n] % MOD << '\n';
    return 0;
}
