const long long LIM = 2000000000000000000LL; // 2·10^18

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n,m; 
    if(!(cin>>n>>m)) return 0;
    vector<long long> h(n+1);
    for(int i=1;i<=n;++i) cin>>h[i];

    vector<vector<int>> out(n+1), in(n+1);
    vector<int> indeg(n+1,0);
    for(int i=0;i<m;++i){
        int u,v;cin>>u>>v;
        out[u].push_back(v);
        in[v].push_back(u);
        ++indeg[v];
    }

    // ترتيب طوبولوجي من القمم ذات الدرجة الصفرية (لا توجد حواف واردة)
    queue<int> q;
    for(int i=1;i<=n;++i) if(indeg[i]==0) q.push(i);
    vector<int> topo;
    while(!q.empty()){
        int u=q.front();q.pop();
        topo.push_back(u);
        for(int v:out[u]){
            if(--indeg[v]==0) q.push(v);
        }
    }
    // حساب المستويات: أعلى مستوى = أكبر قيمة ممكنة بحيث لا يساوي أي مستوى لجاره
    vector<int> lev(n+1,0);
    vector<int> used(n+2,0);
    for(int idx=n-1; idx>=0; --idx){ // نمر بالعقد بترتيب عكسي (من الأوراق إلى الجذور)
        int u = topo[idx];
        // نضع العلامة على مستويات الجيران الصاعدين
        for(int v:out[u]) used[lev[v]] = 1;
        int g=0;
        while(used[g]) ++g; // أصغر مستوى غير مستخدم
        lev[u]=g;
        for(int v:out[u]) used[lev[v]] = 0; // نزيل العلامات
    }

    // حساب XOR لكل مستوى
    int maxLev = 0;
    for(int i=1;i<=n;++i) maxLev = max(maxLev, lev[i]);
    vector<long long> xr(maxLev+1,0);
    for(int i=1;i<=n;++i) xr[lev[i]] ^= h[i];

    // البحث عن أول مستوى قيمته XOR غير صفر
    int winLevel = -1;
    for(int i=0;i<=maxLev;++i){
        if(xr[i]!=0){
            winLevel=i;break;
        }
    }
    if(winLevel==-1){
        cout<<"LOSE\n";
        return 0;
    }

    // نحتاج إلى تعديل عقدة واحدة في هذا المستوى لتجعل XOR يساوي صفر
    long long target = xr[winLevel];
    for(int i=1;i<=n;++i){
        if(lev[i]==winLevel){
            long long newVal = h[i] ^ target; // القيمة الجديدة التي تجعل XOR صفر
            if(newVal<=h[i]){ // يجب أن لا نزيد الضريبة في العقدة المختارة
                h[i] = newVal;
                // بعد تعديل هذه العقدة، يمكن تعديل جميع الجيران الصاعدين بحرية، لذا نضعهم صفرًا (أو أي قيمة) لتبقى اللعبة في حالة خاسرة للخصم
