#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<long long> bit;
    BIT(int n = 0) {init(n);}    
    void init(int n_) {n = n_; bit.assign(n + 1, 0);}    
    void add(int idx, long long val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    long long sum(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    // أول موضع يكون فيه sum(idx) > target
    int upper_bound(long long target) const {
        int idx = 0;
        int mask = 1;
        while (mask << 1 <= n) mask <<= 1; // أقوى قوة 2 <= n
        for (int step = mask; step; step >>= 1) {
            int nxt = idx + step;
            if (nxt <= n && bit[nxt] <= target) {
                target -= bit[nxt];
                idx = nxt;
            }
        }
        return idx + 1; // أول موضع يجاوز target
    }
};

int main() {
    ios::sync_with_stdio(false);
