#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300000 + 5;
int n, k;
string s;
vector<int> belong[MAXN];          // المجموعات التي يحتويها كل مصباح

// هيكلية الاتحاد‑التمييز مع حجم كل مجموعة
int parent[2 * MAXN];
int sz[2 * MAXN];

int find_set(int v) {
    return (v == parent[v]) ? v : parent[v] = find_set(parent[v]);
}

void unite(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a == b) return;
    if (sz[a] < sz[b]) swap(a, b);
    parent[b] = a;
    sz[a] += sz[b];
}

// إرجاع الحد الأدنى للعمليات في مكوّن المتغيّرات x (حقيقة) و x+k (عكس)
int contribution(int x) {
    int y = x + k;                     // الطرف المعاكس
    int fx = find_set(x);
    int fy = find_set(y);
    if (fx == 0) return sz[fy];        // أحد الطرفين مرتبط بالصفر
    if (fy == 0) return sz[fx];
    return min(sz[fx], sz[fy]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    cin >> s;
    s = " " + s; // لجعل الفهارس تبدأ من 1

    // تهيئة DSU: لكل مجموعة i لدينا عقدتان: i (حقيقة) و i+k (عكس)
    for (int i = 1; i <= 2 * k; ++i) {
        parent[i] = i;
        sz[i] = 1;
    }
    // الصفر يمثل الحالة الثابتة (لا يمكن تغييرها)
    parent[0] = 0; sz[0] = 0;

    // قراءة المجموعات وتسجيلها لكل مصباح
    for (int i = 1; i <= k; ++i) {
        int c; cin >> c;
        while (c--) {
            int x; cin >> x;
            belong[x].push_back(i);
        }
    }

    long long answer = 0; // مجموع المساهمات الحالية

    for (int i = 1; i <= n; ++i) {
        if (belong[i].size() == 1) {
            int id = belong[i][0];
            // نزيل المساهمة القديمة للمجموعة
            answer -= contribution(id);
            // ربط أحد الطرفين بالصفر حسب حالة المصباح الأولية
            if (s[i] == '1') {
                // إذا كان المصباح مضاءً، نحتاج أن تكون مجموعة id في الحالة العكسية (تضيف 0)
                parent[find_set(id + k)] = 0;
            } else {
                // إذا كان مطفأً، نحتاج أن تكون مجموعة id في الحالة الحقيقية (تضيف 1)
                parent[find_set(id)] = 0;
            }
            // نضيف المساهمة الجديدة بعد الربط
            answer += contribution(id);
        } else if (belong[i].size() == 2) {
            int a = belong[i][0];
            int b = belong[i][1];
            // نزيل المساهمات القديمة للمجموعتين
            answer -= contribution(a) + contribution(b);
            if (s[i] == '1') {
                // المصباح مضاء → المتغيران يجب أن تكون قيمتهما متساوية
                unite(a, b);
                unite(a + k, b + k);
            } else {
                // المصباح مطفأ → المتغيران يجب أن تكون قيمتهما مختلفة
                unite(a, b + k);
                unite(a + k, b);
            }
            // نضيف المساهمات بعد الدمج
            answer += contribution(a);
        }
        cout << answer << '\n';
    }
    return 0;
}
