#include <bits/stdc++.h>
using namespace std;

struct State {
    long long val;   // أقصى قيمة ممكنة
    bool take;       // هل أخذنا العنصر الحالي أم لا
    int prev;        // عدد العناصر المختارة قبل هذا العنصر
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; 
    if(!(cin >> T)) return 0;
    while (T--) {
        int n, k;
        cin >> n >> k;
        vector<long long> a(n), b(n);
        for (int i = 0; i < n; ++i) cin >> a[i] >> b[i];

        // ترتيب المؤشرات بحسب b تنازلياً (لأننا سنختار وفقاً لهذا الترتيب)
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int i, int j){
            if (b[i] != b[j]) return b[i] > b[j];
            return a[i] > a[j];
        });

        // dp[j] = أقصى قيمة بعد معالجة بعض العناصر واختيار j منها
        const long long NEG = -(1LL<<60);
        vector<long long> dp(k+1, NEG), ndp(k+1, NEG);
        vector<vector<State>> trace(n, vector<State>(k+1));
        dp[0] = 0; // لا شيء مختار
        for (int pos = 0; pos < n; ++pos) {
            int id = idx[pos];
            fill(ndp.begin(), ndp.end(), NEG);
            for (int cnt = 0; cnt <= k; ++cnt) {
                // عدم اختيار العنصر
                if (dp[cnt] > ndp[cnt]) {
                    ndp[cnt] = dp[cnt];
                    trace[pos][cnt] = {dp[cnt], false, cnt};
                }
                // اختيار العنصر إذا كان هناك مساحة
                if (cnt+1 <= k && dp[cnt] != NEG) {
                    long long add = a[id] + b[id] * cnt; // cnt هو عدد الوحوش المختارة قبله
                    long long cand = dp[cnt] + add;
                    if (cand > ndp[cnt+1]) {
                        ndp[cnt+1] = cand;
                        trace[pos][cnt+1] = {cand, true, cnt};
                    }
                }
            }
            dp.swap(ndp);
        }

        // نختار أفضل قيمة بين 0..k (قد لا نحتاج ملء k كامل إذا كان بعض b سالباً، لكن b غير سالب في المسألة)
        int bestCnt = 0;
        for (int cnt = 1; cnt <= k; ++cnt) {
            if (dp[cnt] > dp[bestCnt]) bestCnt = cnt;
        }

        // استرجاع العناصر المختارة
        vector<int> chosen;
        int curCnt = bestCnt;
        for (int pos = n-1; pos >= 0; --pos) {
            State st = trace[pos][curCnt];
            if (st.take) {
                chosen.push_back(idx[pos]); // العنصر المختار
                curCnt = st.prev;
            } else {
                curCnt = st.prev;
            }
        }
        reverse(chosen.begin(), chosen.end()); // الآن بترتيب b تنازلياً

        // بناء قائمة الأفعال
        vector<int> actions;
        // 1- استدعاء الوحوش المختارة بترتيبها (b تنازلياً)
        for (int id : chosen) actions.push_back(id + 1); // الأرقام 1‑‑‑n في الإدخال
        // 2- لكل وحش غير مختار: استدعاء ثم تدمير
        vector<bool> isChosen(n,false);
        for (int id: chosen) isChosen[id]=true;
        for (int i = 0; i < n; ++i) {
            if (!isChosen[i]) {
                actions.push_back(i+1);   // استدعاء
                actions.push_back(-(i+1)); // تدمير فوراً
            }
        }

        cout << actions.size() << '\n';
        for (size_t i = 0; i < actions.size(); ++i) {
            if (i) cout << ' ';
            cout << actions[i];
        }
        cout << '\n';
    }
    return 0;
}
