            if c == d:
                # كلا الزوجين متساويين
                if a == c:
                    # جميعهم متساويين → نحتاج لتغيير خلية واحدة من كل زوج
                    ops.append((n-1, n))   # (n-1,n)
                    ops.append((n, n-1))   # (n,n-1)
                else:
                    # a==b != c==d → لا حاجة لتغيير شيء
                    pass
            else:
                # c و d مختلفان، نحتاج لجعلهما متساويين مع القيمة المعاكسة لـ a
                if a == c:
                    ops.append((n-1, n))
                else:
                    ops.append((n, n-1))
        else:
            # a و b مختلفان
