                    ops.append((2, 1))
                    ops.append((n, n-1))
                elif b == c:
                    ops.append((1, 2))
                    ops.append((n-1, n))
                else:
                    ops.append((1, 2))
                    ops.append((n, n-1))
        # طباعة النتيجة
        out_lines.append(str(len(ops)))
        for x, y in ops:
            out_lines.append(f"{x} {y}")
