using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double A, B, C;
    if(!(cin >> A >> B >> C)) return 0;
    const double EPS = 1e-9;
    vector<double> roots;

    if (fabs(A) < EPS) { // معادلة خطية أو ثابتة
        if (fabs(B) < EPS) {
            if (fabs(C) < EPS) {
                cout << -1; // عدد لا نهائي من الجذور
                return 0;
            } else {
                cout << 0; // لا جذور
                return 0;
            }
        } else {
            roots.push_back(-C / B);
        }
    } else {
        double D = B * B - 4.0 * A * C;
        if (D > EPS) {
            double sqrtD = sqrt(D);
            roots.push_back((-B - sqrtD) / (2.0 * A));
            roots.push_back((-B + sqrtD) / (2.0 * A));
        } else if (fabs(D) < EPS) {
            roots.push_back(-B / (2.0 * A));
        } // إذا كان D < 0 لا توجد جذور
    }

    if (roots.empty()) {
        cout << 0;
        return 0;
    }

    sort(roots.begin(), roots.end());
    // إزالة التكرارات إذا كان هناك جذرين متقاربين بسبب الأخطاء العددية
    vector<double> uniq;
    for (double r : roots) {
        if (uniq.empty() || fabs(r - uniq.back()) > EPS) uniq.push_back(r);
    }

    cout << uniq.size() << '\n';
    cout.setf(ios::fixed);
    cout << setprecision(10);
    for (double r : uniq) {
        cout << r << '\n';
    }
    return 0;
}
