#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, R, C;
    if(!(cin >> n >> R >> C)) return 0;
    vector<string> w(n+1);
    for(int i=1;i<=n;i++) cin >> w[i];

    // طول كل كلمة
    vector<int> len(n+1);
    for(int i=1;i<=n;i++) len[i]= (int)w[i].size();

    // next[i] = أول كلمة لا يمكن وضعها في السطر إذا بدأنا من i
    vector<int> nxt(n+2);
    int j=1, cur=0; // j هو نهاية النافذة (غير شامل)
    for(int i=1;i<=n;i++){
        if(j<i){ j=i; cur=0; }
        while(j<=n && cur + len[j] + (cur==0?0:1) <= C){
            cur += len[j] + (cur==0?0:1);
            ++j;
        }
        nxt[i]=j; // j هو أول كلمة لا يمكن وضعها
        // تحريك النافذة من اليسار
        cur -= len[i] + (i+1<j?1:0);
    }
    nxt[n+1]=n+1;

    // بناء جدول الرفع الثنائي
    const int LOG = 20; // لأن R ≤ 10⁶ < 2^20
    vector<vector<int>> jump(LOG, vector<int>(n+2));
    for(int i=1;i<=n+1;i++) jump[0][i]=nxt[i];
    for(int k=1;k<LOG;k++)
        for(int i=1;i<=n+1;i++)
            jump[k][i]=jump[k-1][ jump[k-1][i] ];

    // إيجاد البداية التي تعطي أكبر عدد من الكلمات بعد R سطرًا
    int bestStart=1, bestLen=0;
    for(int i=1;i<=n;i++){
        int pos=i;
        int steps=R;
        for(int k=0; steps; k++){
            if(steps & 1) pos = jump[k][pos];
            steps >>= 1;
        }
