import sys

def count_balanced(s: str) -> int:
    n = len(s)
    total = n * (n + 1) // 2  # جميع الأجزاء
    subtract = 0
    cur = 0
    for ch in s:
        if ch == '7':
            cur += 1
        else:
            if cur:
                subtract += cur * (cur + 1) // 2
                cur = 0
    if cur:
