#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if(!(cin >> n >> m >> k)) return 0;
    vector<pair<int,int>> edges(m);
    vector<vector<int>> adj(n);
    vector<int> deg(n,0);

    for(int i=0;i<m;++i){
        int x,y;cin>>x>>y;--x;--y;
        edges[i]={x,y};
        adj[x].push_back(y);
        adj[y].push_back(x);
        ++deg[x]; ++deg[y];
    }

    // حالة الحذف للقمم
    vector<char> removed(n,0);
    queue<int> q;
    int alive=n;
    // حذف القمم التي درجتها أقل من k في الرسم الكامل
    for(int i=0;i<n;++i){
        if(deg[i] < k){
            q.push(i);
            removed[i]=1;
            --alive;
        }
    }
    while(!q.empty()){
        int v=q.front(); q.pop();
        for(int to: adj[v]){
            if(removed[to]) continue;
            if(--deg[to] < k){
                removed[to]=1;
                q.push(to);
                --alive;
            }
        }
    }

    vector<int> ans; ans.reserve(m);
    ans.push_back(alive); // بعد إضافة كل الحواف (اليوم الأخير)

    // معالجة الحواف بالعكس
    for(int i=m-1;i>0;--i){ // نبدأ من الحافة الأخيرة إلى الثانية
        auto [u,v]=edges[i];
        // حذف الحافة من الرسم الحالي
        if(!removed[u] && !removed[v]){
            if(--deg[u] < k){
                removed[u]=1; q.push(u); --alive;
            }
            if(--deg[v] < k){
                removed[v]=1; q.push(v); --alive;
            }
            while(!q.empty()){
                int cur=q.front(); q.pop();
                for(int nb: adj[cur]){
                    if(removed[nb]) continue;
                    if(--deg[nb] < k){
                        removed[nb]=1; q.push(nb); --alive;
                    }
                }
            }
        }
        ans.push_back(alive);
    }

    // طباعة النتائج بترتيب الأيام الأصلي
    for(int i=m-1;i>=0;--i){
        cout << ans[i] << '\n';
    }
    return 0;
}
