```cpp
#include <bits/stdc++.h>
using namespace std;
const int MOD = 998244353;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    if (!(cin >> n >> k)) return 0;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; ++i) cin >> a[i];

    vector<int> freq(n + 1, 0);          // لأن القيم لا تتجاوز n
    int uniqOnce = 0;                    // عدد القيم التي تظهر مرة واحدة في النافذة الحالية
    int left = 1;                        // بداية النافذة الحالية

    vector<int> dp(n + 1, 0), pref(n + 1, 0);
    dp[0] = 1;
    pref[0] = 1;                         // pref[i] = (dp[0] + … + dp[i]) % MOD

    for (int right = 1; right <= n; ++right) {
        // أضف العنصر a[right] إلى النافذة
        int val = a[right];
        ++freq[val];
        if (freq[val] == 1) ++uniqOnce;          // ظهر لأول مرة
        else if (freq[val] == 2) --uniqOnce;    // لم يعد فريداً

        // إذا تجاوزنا الحد k، حرك المؤشر الأيسر حتى يصبح الشرط محققاً
        while (uniqOnce > k) {
            int v = a[left];
            --freq[v];
            if (freq[v] == 1) ++uniqOnce;        // عاد ليصبح فريداً مرة أخرى
            else if (freq[v] == 0) --uniqOnce;   // اختفى تماماً
            ++left;
        }

        // الآن كل بداية i بين left و right صالحة للقطعة الأخيرة
        // dp[right] = sum_{i=left}^{right} dp[i-1]
        int lIdx = left - 2; // index قبل (left-1) في مصفوفة pref
        int sum = pref[right - 1];
        if (lIdx >= 0) sum = (sum - pref[lIdx] + MOD) % MOD;
        dp[right] = sum;
        pref[right] = (pref[right - 1] + dp[right]) % MOD;
    }

    cout << dp[n] % MOD << '\n';
    return 0;
}
