// شجرة فِنْك لتخزين مجموع الأعداد المتبقية
struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n = 0) {init(n);}    
    void init(int n_) {n = n_; bit.assign(n + 2, 0);}    
    void add(int idx, long long val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    long long sum(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    // إيجاد أصغر فهرس بحيث يكون المجموع حتى هذا الفهرس >= target
    int lower_bound(long long target) const {
        int idx = 0;
        int mask = 1;
        while (mask << 1 <= n) mask <<= 1; // أعلى قوة 2 <= n
        for (int k = mask; k; k >>= 1) {
            int nxt = idx + k;
            if (nxt <= n && bit[nxt] < target) {
                target -= bit[nxt];
                idx = nxt;
            }
        }
        return idx + 1; // الفهرس المطلوب
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; 
    if(!(cin >> n)) return 0;
    vector<long long> s(n+1);
    for (int i = 1; i <= n; ++i) cin >> s[i];

    Fenwick ft(n);
    // نملأ الشجرة بالأعداد 1..n
    for (int i = 1; i <= n; ++i) ft.add(i, i);

    vector<int> p(n+1);
    // نعيد بناء التبديلة من الخلف إلى الأمام
    for (int i = n; i >= 1; --i) {
