        // البحث عن أصغر فهرس يحقق المجموع >= need
        int pos = ft.lower_bound(need);
        p[i] = pos;               // العنصر في الموضع i هو pos
        ft.add(pos, -pos);        // نحذف هذا العنصر من الشجرة
    }

    for (int i = 1; i <= n; ++i) {
        if (i) cout << ' ';
        cout << p[i];
