#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; 
    if(!(cin>>n)) return 0;
    vector<int> p(n+1);
    for(int i=1;i<=n;i++) cin>>p[i];
    // موضع كل قيمة
    vector<int> pos(n+1);
    for(int i=1;i<=n;i++) pos[p[i]] = i;

    // شجرة فِنك لحساب عدد الانقلابات
    vector<int> bit(n+2,0);
    auto add = [&](int idx){ for(; idx<=n; idx+=idx&-idx) bit[idx]++; };
    auto sum = [&](int idx){ int s=0; for(; idx>0; idx-=idx&-idx) s+=bit[idx]; return s; };

    long long inv = 0;               // الانقلابات حتى الآن
    long long leftSum = 0, rightSum = 0; // مجموع القيم a_i على الطرفين
    priority_queue<long long> L; // max‑heap للقيم الأصغر أو يساوي الوسيط
    priority_queue<long long, vector<long long>, greater<long long>> R; // min‑heap للقيم الأكبر
    long long median = 0; // قيمة الوسيط الحالية
    vector<long long> answer(n+1);

    for(int k=1;k<=n;k++){
        // 1) تحديث عدد الانقلابات بإضافة العنصر k
        int pk = pos[k];
        inv += (k-1) - sum(pk); // عدد العناصر السابقة التي تقع بعده
        add(pk);

        // 2) قيمة a_k = pos_k - k
        long long a = (long long)pk - k;
        // إدخال a في هيكلين القمم مع الحفاظ على التوازن
        if(L.empty() || a <= median){
            L.push(a);
            leftSum += a;
        }else{
            R.push(a);
            rightSum += a;
        }
        // تعديل التوازن بحيث حجم L يساوي حجم R أو أكبر بواحد
        if((int)L.size() > (int)R.size()+1){
            long long mv = L.top(); L.pop(); leftSum -= mv;
            R.push(mv); rightSum += mv;
        }else if((int)L.size() < (int)R.size()){
            long long mv = R.top(); R.pop(); rightSum -= mv;
            L.push(mv); leftSum += mv;
        }
        median = L.top();
        // حساب Σ|a_i - median|
        long long leftCnt = L.size();
        long long rightCnt = R.size();
        long long cost = median*leftCnt - leftSum + rightSum - median*rightCnt;
        // f(k) هو مجموع الانقلابات + cost
        answer[k] = inv + cost;
    }

    for(int k=1;k<=n;k++){
        cout<<answer[k];
        if(k<n) cout<<' ';
    }
    cout<<"\n";
    return 0;
}
