#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300000 + 5;

int n, k;
string s;
vector<int> belong[MAXN];               // المجموعات التي يحتويها كل مصباح

int parent[2 * MAXN];                    // تمثيل DSU: 1..k   -> الحالة 0 (تشغيل)
                                          // k+1..2k -> الحالة 1 (عدم تشغيل)
int sz[2 * MAXN];                        // حجم كل مكوّن متصل

int find_set(int v) {
    return (parent[v] == v) ? v : parent[v] = find_set(parent[v]);
}

void unite(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a == b) return;
    // ندمج b إلى a
    parent[b] = a;
    sz[a] += sz[b];
}

// تعيد الحد الأدنى للعمليات المطلوبة للمكوّن الذي يضم العقدة x
int contribution(int x) {
    int y = (x <= k) ? x + k : x - k;   // الطرف المقابل (الحالة المعاكسة)
    int fx = find_set(x);
    int fy = find_set(y);
    if (fx == 0) return sz[fy];        // أحد الطرفين ثابت (مرتبط بـ 0)
    if (fy == 0) return sz[fx];
    // كلا الطرفين حرين → نختار الأصغر
    return min(sz[fx], sz[fy]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> k)) return 0;
    cin >> s;
    s = " " + s; // لتصبح الفهارس 1‑‑‑

    // تهيئة DSU
    for (int i = 0; i <= 2 * k; ++i) {
        parent[i] = i;
        sz[i] = 0;
    }
    for (int i = 1; i <= k; ++i) {
        sz[i] = 1;          // الحالة 0 (تشغيل)
        sz[i + k] = 1;      // الحالة 1 (عدم تشغيل)
    }
    // العقدة 0 تمثل الحالة الثابتة (مربوطة دائماً بـ 0)
    parent[0] = 0; sz[0] = 0;

    // قراءة المجموعات وتسجيل وجودها في كل مصباح
    for (int i = 1; i <= k; ++i) {
        int c; cin >> c;
        while (c--) {
            int x; cin >> x;
            belong[x].push_back(i);
        }
    }

    long long answer = 0; // مجموع الحد الأدنى حتى الآن
    for (int i = 1; i <= n; ++i) {
        if (belong[i].size() == 1) {
            int id = belong[i][0];
            // نزيل المساهمة القديمة للمكوّن المتعلق بالمجموعة id
            answer -= contribution(id);
            // إذا كان المصباح مضاءً نربط الحالة المعاكسة بـ 0، وإلا نربط الحالة الأصلية بـ 0
            if (s[i] == '1') {
                // نربط الحالة (id + k) بـ 0
                parent[find_set(id + k)] = 0;
            } else {
                parent[find_set(id)] = 0;
            }
            // نضيف المساهمة الجديدة بعد الربط
            answer += contribution(id);
        } else if (belong[i].size() == 2) {
            int a = belong[i][0];
            int b = belong[i][1];
            if (s[i] == '1') {
                // نحتاج أن تكون الحالة (a) مختلفة عن الحالة (b)
                if (find_set(a) != find_set(b)) {
                    answer -= contribution(a) + contribution(b);
                    unite(a, b);
                    unite(a + k, b + k);
                    answer += contribution(a);
                }
            } else {
                // نحتاج أن تكون الحالة (a) مساوية للحالة (b) مع عكس أحدهما
                if (find_set(a + k) != find_set(b)) {
                    answer -= contribution(a) + contribution(b);
                    unite(a + k, b);
                    unite(a, b + k);
                    answer += contribution(a);
                }
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
