// دالة تُعيد قيمة العنصر في الموضع pos (1‑‑‑‑‑>1‑‑‑‑‑n·(n‑1)+1)
long long getValue(long long n, long long pos) {
    if (pos == n * (n - 1) + 1) return 1; // العنصر الأخير هو 1
    // نبحث عن i بحيث يكون pos داخل الكتلة الخاصة به
    long long i = 1;
    while (true) {
        long long block = 2 * (n - i);
