            pos -= block;
            ++i;
        } else {
            break;
        }
    }
    // داخل الكتلة i، الموضع يبدأ من 1
    // إذا كان الموضع فرديًا نطبع i، وإلا نطبع i + (pos/2)
    if (pos % 2 == 1) return i;
    else return i + pos / 2;
}

