struct Minion {
    long long a, b;
    int idx; // رقم الوحدة الأصلي
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; cin >> T;
    while (T--) {
        int n, k; cin >> n >> k;
        vector<Minion> v(n);
        for (int i = 0; i < n; ++i) {
            cin >> v[i].a >> v[i].b;
            v[i].idx = i + 1; // الأرقام تبدأ من 1 حسب المطلوب في الإخراج
        }
        // فرز حسب b تنازلياً (وإذا تساوى b نفضّل a الأكبر لتقليل التعقيد)
        sort(v.begin(), v.end(), [](const Minion& x, const Minion& y){
            if (x.b != y.b) return x.b > y.b;
            return x.a > y.a;
        });

        // DP[i][j] = أقصى قوة بعد النظر في أول i وحدة واختيار j منها
        const long long NEG = -(1LL<<60);
        vector<vector<long long>> dp(n+1, vector<long long>(k+1, NEG));
        vector<vector<char>> take(n+1, vector<char>(k+1, 0)); // لتتبع الاختيار
        dp[0][0] = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= k; ++j) {
                // لا نأخذ الوحدة i
                if (dp[i-1][j] > dp[i][j]) {
                    dp[i][j] = dp[i-1][j];
                    take[i][j] = 0;
                }
                // نأخذ الوحدة i إذا كان j>0
                if (j > 0 && dp[i-1][j-1] != NEG) {
                    long long val = dp[i-1][j-1] + v[i-1].a + v[i-1].b * (j-1);
                    if (val > dp[i][j]) {
                        dp[i][j] = val;
                        take[i][j] = 1; // أخذناها
                    }
                }
            }
        }
        // اختيار أفضل j (قد يكون أقل من k إذا كان ذلك يعطي نفس القيمة القصوى)
        int bestJ = 0;
        for (int j = 0; j <= k; ++j) {
            if (dp[n][j] > dp[n][bestJ]) bestJ = j;
        }
        // استرجاع الوحدات المختارة
        vector<int> chosen; // تخزين أرقام الوحدات المختارة
        int i = n, j = bestJ;
        while (i > 0) {
            if (take[i][j]) {
                chosen.push_back(v[i-1].idx);
                --j;
            }
            --i;
        }
        // الآن chosen تحتوي على الوحدات المختارة لكن بترتيب عكسي (من الأخير إلى الأول)
        // نعيدها إلى الترتيب الذي استدعينا فيه: وهو نفس ترتيب v (b تنازلي)
        reverse(chosen.begin(), chosen.end());

        // نطبع عدد الإجراءات = عدد الوحدات المختارة (لا نحتاج إلى تدمير)
        cout << chosen.size() << '\n';
        for (size_t p = 0; p < chosen.size(); ++p) {
            if (p) cout << ' ';
            cout << chosen[p];
        }
        if (!chosen.empty()) cout << '\n';
        else cout << '\n'; // حالة لا نختار أي وحدة
    }
    return 0;
}
