    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    double A, B, C;
    if (!(cin >> A >> B >> C)) return 0;
    const double EPS = 1e-9;

    // الحالة عندما يكون A = 0
    if (fabs(A) < EPS) {
        if (fabs(B) < EPS) {
            if (fabs(C) < EPS) {
                cout << -1;               // عدد لا نهائي من الجذور
            } else {
                cout << 0;                // لا جذور
            }
        } else {
            double root = -C / B;
            cout << 1 << '\n';
            cout << fixed << setprecision(10) << root;
        }
        return 0;
    }

    // حساب المميز Δ
    double D = B * B - 4.0 * A * C;
    if (D < -EPS) {
        cout << 0;                        // لا جذور حقيقية
        return 0;
    }

    vector<double> roots;
    if (fabs(D) < EPS) {                  // جذر واحد
        roots.push_back(-B / (2.0 * A));
    } else {                              // جذران
        double sqrtD = sqrt(D);
        double x1 = (-B + sqrtD) / (2.0 * A);
        double x2 = (-B - sqrtD) / (2.0 * A);
        roots.push_back(x1);
        roots.push_back(x2);
    }

    // حذف التكرارات الناتجة عن الأخطاء العائمة
    sort(roots.begin(), roots.end());
    vector<double> distinct;
    for (double r : roots) {
        if (distinct.empty() || fabs(r - distinct.back()) > EPS) {
            distinct.push_back(r);
        }
    }

    cout << distinct.size() << '\n';
    cout << fixed << setprecision(10);
    for (double r : distinct) {
        cout << r << '\n';
    }
    return 0;
}
