string toBase(int n, int k) {
    string res;
    while (n > 0) {
        int digit = n % k;          // الباقي هو الرقم في هذه الخانة
        res.push_back('0' + digit); // لأن k ≤ 10 يمكن استعمال الأرقام العادية
        n /= k;
    }
    reverse(res.begin(), res.end());
    return res;
}

