// تمثيل النقطة كمفتاح واحد في مجموعة hash
static inline long long encode(int x, int y) {
    return (static_cast<long long>(x) << 32) | static_cast<unsigned int>(y);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<pair<int,int>> pts(n);
    unordered_set<long long> S;
    S.reserve(n * 2);
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        pts[i] = {x, y};
        S.insert(encode(x, y));
    }

    // تجميع النقاط حسب إحداثي x لتقليل عدد الفحوصات
    unordered_map<int, vector<int>> col;
    col.reserve(n);
    for (auto &p : pts) {
        col[p.first].push_back(p.second);
    }
    for (auto &kv : col) {
        sort(kv.second.begin(), kv.second.end());
    }

    long long ans = 0;
    // لكل عمود، نفحص كل زوج من النقاط داخل العمود نفسه
    for (auto &kv : col) {
        int x = kv.first;
        const vector<int> &ys = kv.second;
        int m = ys.size();
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                int len = ys[j] - ys[i]; // طول الضلع
                // تحقق من وجود العمود الأيمن
                if (S.find(encode(x + len, ys[i])) != S.end() &&
                    S.find(encode(x + len, ys[j])) != S.end()) {
                    ++ans;
                }
                // تحقق من وجود العمود الأيسر (للتأكد من عدم فقد المربعات التي تمت عدّها من الجهة اليمنى)
                if (S.find(encode(x - len, ys[i])) != S.end() &&
                    S.find(encode(x - len, ys[j])) != S.end()) {
                    ++ans;
                }
            }
        }
    }

    // كل مربع يُحصى مرتين (من العمود الأيسر ومن العمود الأيمن)، لذا نقسم على 2
    cout << ans / 2 << '\n';
    return 0;
}
