public class Main {
    public static void main(String[] args) throws IOException {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.flush();
    }

    private static void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();   // عدد اللترات المطلوب
        int a = in.nextInt();   // عدد زجاجات نصف لتر
        int b = in.nextInt();   // عدد زجاجات واحد لتر
        int c = in.nextInt();   // عدد زجاجات اثنين لتر

        long ways = 0L;
        // نجرب جميع أعداد الزجاجات من النوعين الأكبر
        for (int i = 0; i <= b; i++) {               // i = عدد زجاجات 1 لتر
            for (int j = 0; j <= c; j++) {           // j = عدد زجاجات 2 لتر
                int volume = i + 2 * j;              // الحجم المستهلك باللترات
                if (volume > n) continue;            // تجاوز المطلوب
                int remaining = n - volume;          // ما يبقى من اللترات
                // نحتاج إلى 2 * remaining زجاجات نصف لتر
                if (2L * remaining <= a) {
                    ways++;
                }
            }
        }
        out.println(ways);
    }

    // قارئ إدخال بسيط
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

