        static final double eps = 0.000000001;
        static final long mod = 1000000007;

        void solve(InputReader in, PrintWriter out) throws IOException {

            int N = in.nextInt();
            int A = in.nextInt();
            int B = in.nextInt();
            int C = in.nextInt();

            int count = 0;
            for (int i = 0; i <= B; i++)
                for (int j = 0; j <= C; j++) {
                    int sum = i + j * 2;
                    if (sum == N) {
                        count++;
                    } else if (sum < N) {
                        int rem = N - sum;
                        if (rem * 2 <= A) count++;
                    }
                }

            out.println(count);

        }
    }

