#include <bits/stdc++.h>
using namespace std;

struct SegTree {
    int n;                       // عدد الأيام
    vector<long long> sumB;      // مجموع min(orders, b) لكل عقدة
    vector<long long> sumA;      // مجموع min(orders, a) لكل عقدة
    vector<int> orders;          // عدد الطلبات الفعلي لكل يوم
    int a, b;                    // السعات بعد/قبل الصيانة

    SegTree(int n_, int a_, int b_) : n(n_), a(a_), b(b_) {
        sumB.assign(4 * n + 5, 0);
        sumA.assign(4 * n + 5, 0);
        orders.assign(n + 1, 0);
    }

    // تحديث قيمة اليوم idx بعد إضافة x طلبات
    void addOrder(int idx, int x) {
        orders[idx] += x;
        _update(1, 1, n, idx);
    }

    // استعلام مجموع القيم من l إلى r باستخدام النوع 0 = قبل الصيانة (b) أو 1 = بعد الصيانة (a)
    long long queryRange(int l, int r, int type) const {
        if (l > r) return 0;
        return _query(1, 1, n, l, r, type);
    }

private:
    void _update(int node, int l, int r, int idx) {
        if (l == r) {
            sumB[node] = min(orders[idx], b);
            sumA[node] = min(orders[idx], a);
            return;
        }
        int mid = (l + r) >> 1;
        if (idx <= mid) _update(node << 1, l, mid, idx);
        else _update(node << 1 | 1, mid + 1, r, idx);
        sumB[node] = sumB[node << 1] + sumB[node << 1 | 1];
        sumA[node] = sumA[node << 1] + sumA[node << 1 | 1];
    }

    long long _query(int node, int l, int r, int ql, int qr, int type) const {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) {
            return (type == 0) ? sumB[node] : sumA[node];
        }
        int mid = (l + r) >> 1;
        return _query(node << 1, l, mid, ql, qr, type) +
               _query(node << 1 | 1, mid + 1, r, ql, qr, type);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, a, b, q;
    if (!(cin >> n >> k >> a >> b >> q)) return 0;
    SegTree st(n, a, b);

    for (int i = 0; i < q; ++i) {
        int type; cin >> type;
        if (type == 1) {
            int d, x; cin >> d >> x;
            st.addOrder(d, x);
        } else { // type == 2
            int p; cin >> p;
            long long before = st.queryRange(1, p - 1, 0);          // باستخدام السعة b
            long long after  = st.queryRange(p + k, n, 1);          // باستخدام السعة a
            cout << before + after << '\n';
        }
    }
    return 0;
}
