#include <bits/stdc++.h>
using namespace std;

struct BipartiteDSU {
    vector<int> parent, sz, col; // col: اللون بالنسبة للجذر
    BipartiteDSU(int n = 0) { init(n); }
    void init(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        col.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }
    // إيجاد الجذر مع تحديث اللون بالنسبة للجذر
    int find(int x) {
        if (parent[x] == x) return x;
        int p = parent[x];
        parent[x] = find(parent[x]);
        col[x] ^= col[p]; // اللون يضيف لون الأب
        return parent[x];
    }
    // إرجاع اللون (0 أو 1) بعد الضغط الكامل
    int getColor(int x) { find(x); return col[x]; }
    // دمج x و y مع فرض أن لونهما مختلف (parity = 1)
    // تُعيد true إذا تم الدمج بنجاح، false إذا كان هناك تعارض (أي أن x و y يجب أن يكونا في مجموعتين مختلفتين لكنهما في نفس المجموعة الآن)
    bool unite(int x, int y) {
        int rx = find(x), ry = find(y);
        int cx = getColor(x), cy = getColor(y);
        if (rx == ry) {
            // إذا كان اللونين متساويين فهناك تعارض لأننا نريد أن يكونا مختلفين
            return (cx ^ cy) == 1; // إذا كان مختلفين فكل شيء سليم، وإلا تعارض
        }
        // نريد أن نجعل اللونين مختلفين، أي (cx ^ col_between ^ cy) = 1
        // نختار ربط rx تحت ry
        if (sz[rx] < sz[ry]) {
            swap(rx, ry);
            swap(cx, cy);
        }
        parent[ry] = rx;
        // نحدد لون الجذر ry بالنسبة للrx بحيث يتحقق الشرط
        // نحتاج إلى: cx ^ col_ry ^ cy = 1  => col_ry = cx ^ cy ^ 1
        col[ry] = cx ^ cy ^ 1;
        sz[rx] += sz[ry];
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    if (!(cin >> n >> m >> q)) return 0;
    struct Edge {int u, v; long long w; int idx;};
    vector<Edge> edges(m);
    for (int i = 0; i < m; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
        --edges[i].u; --edges[i].v;
        edges[i].idx = i; // رقم الطريق الأصلي
    }
    // نرتب الطرق تنازلياً حسب الوزن مرة واحدة
    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return edges[a].w > edges[b].w; });

    while (q--) {
        int l, r; // 1‑based في الإدخال
        cin >> l >> r;
        --l; --r;
        BipartiteDSU dsu(n);
        long long answer = -1; // إذا لم يحدث تعارض يبقى -1
        for (int id : order) {
            if (id < l || id > r) continue; // الطريق غير موجود في النطاق
            int u = edges[id].u;
            int v = edges[id].v;
            // نريد أن يكون u و v في مجموعتين مختلفتين
            if (!dsu.unite(u, v)) { // تعارض
                answer = edges[id].w;
                break;
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
