#include <bits/stdc++.h>
using namespace std;

struct State {
    int cnt;   // عدد القوارير المستخدمة
    int keep;  // كمية الصودا التي تبقى داخل القوارير المختارة
    State(int c = -1, int k = -1) : cnt(c), keep(k) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; 
    if(!(cin >> n)) return 0;
    vector<int> a(n), b(n);
    int total = 0;          // مجموع الصودا المتبقية
    int maxCap = 0;         // مجموع السعات الكلية (حد أعلى للـ DP)
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
        total += a[i];
    }
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
        maxCap += b[i];
    }

    // DP: dp[سعة] = أفضل حالة (أقل عدد قوارير، وأكبر كمية صودا تبقى داخلها)
    vector<State> dp(maxCap + 1, State());
    dp[0] = State(0, 0); // لا نستخدم قوارير ولا نحتفظ بصودا

    for (int i = 0; i < n; ++i) {
        // نحدث DP من النهاية إلى البداية لتجنب استخدام القارورة نفسها أكثر من مرة
        for (int s = maxCap - b[i]; s >= 0; --s) {
            if (dp[s].cnt == -1) continue; // حالة غير reachable
            int ns = s + b[i];
            State cand(dp[s].cnt + 1, dp[s].keep + a[i]);
            if (dp[ns].cnt == -1 || cand.cnt < dp[ns].cnt ||
                (cand.cnt == dp[ns].cnt && cand.keep > dp[ns].keep)) {
                dp[ns] = cand;
            }
        }
    }

    // البحث عن أفضل حل يحقق سعة >= total
    int bestCnt = INT_MAX;
    int bestKeep = 0;
    for (int s = total; s <= maxCap; ++s) {
        if (dp[s].cnt == -1) continue;
        if (dp[s].cnt < bestCnt) {
            bestCnt = dp[s].cnt;
            bestKeep = dp[s].keep;
        } else if (dp[s].cnt == bestCnt && dp[s].keep > bestKeep) {
            bestKeep = dp[s].keep;
        }
    }

    int minTime = total - bestKeep; // الصودا التي يجب نقلها
    cout << bestCnt << ' ' << minTime << '\n';
    return 0;
}
