    vector<pair<int,int>> edges(m);
    vector<vector<int>> adj(n);          // قائمة الجيران المتجهية
    vector<int> deg(n,0);                // درجة كل عقدة

    for(int i=0;i<m;++i){
        int x,y;cin>>x>>y;--x;--y;
        edges[i]={x,y};
        adj[x].push_back(y);
        adj[y].push_back(x);
        ++deg[x]; ++deg[y];
    }

    vector<char> removed(n,0);           // 0 = موجود، 1 = محذوف
    queue<int> q;
    int alive=n;
    // حذف القمم التي درجتها أقل من k في الحالة النهائية
    for(int i=0;i<n;++i){
        if(deg[i] < k && !removed[i]){
            q.push(i);
            removed[i]=1;
            --alive;
        }
    }
    while(!q.empty()){
        int v=q.front(); q.pop();
        for(int to: adj[v]){
            if(removed[to]) continue;
            if(--deg[to] < k){
                removed[to]=1;
                q.push(to);
                --alive;
            }
        }
    }

    vector<int> ans; ans.reserve(m);
    ans.push_back(alive); // بعد اليوم الأخير

    // معالجة الأيام بالعكس
    for(int i=m-1;i>0;--i){
        auto [a,b]=edges[i];
        // حذف الحافة (a,b) من الرسم البياني العكسي
        // نخفض درجتي الطرفين إذا لم يكونا محذوفين
        if(!removed[a] && !removed[b]){
            if(--deg[a] < k){
                removed[a]=1; q.push(a); --alive;
            }
            if(--deg[b] < k){
                removed[b]=1; q.push(b); --alive;
            }
            while(!q.empty()){
                int v=q.front(); q.pop();
                for(int to: adj[v]){
                    if(removed[to]) continue;
                    if(--deg[to] < k){
                        removed[to]=1; q.push(to); --alive;
                    }
                }
            }
        }
        ans.push_back(alive);
    }

    // طباعة النتائج بالترتيب من اليوم الأول إلى الأخير
    for(int i=ans.size()-1;i>=0;--i){
        cout << ans[i] << '\n';
