    dp[0] = 1;
    pref[0] = 1;                     // pref[i] = (dp[0] + … + dp[i]) % MOD

    for (int i = 1; i <= n; ++i) {
        // أضف العنصر a[i] إلى النافذة
        if (cnt[a[i]] == 0) uniqOne++;
        else if (cnt[a[i]] == 1) uniqOne--;
        cnt[a[i]]++;

        // إذا تجاوزنا الحد k، حرك L إلى اليمين حتى يصبح الشرط صحيحاً
        while (uniqOne > k) {
            // احذف العنصر a[L] من النافذة
            if (cnt[a[L]] == 1) uniqOne--;          // سيصبح 0 بعد الحذف
            else if (cnt[a[L]] == 2) uniqOne++;    // كان 2 سيصبح 1
            cnt[a[L]]--;
            ++L;
        }

        // الآن كل j بحيث L-1 ≤ j ≤ i-1 يعطي قطعة صالحة
        // dp[i] = pref[i-1] - pref[L-2]
        int leftIdx = L - 2; // قد يكون -1 عندما L == 1
        long long sum = pref[i-1];
        if (leftIdx >= 0) sum = (sum - pref[leftIdx] + MOD) % MOD;
        dp[i] = (int)sum;
        pref[i] = (pref[i-1] + dp[i]) % MOD;
    }

    cout << dp[n] % MOD << '\n';
    return 0;
}
