    int winLevel=-1;
    for(int i=0;i<=maxLevel;i++) if(xorLevel[i]!=0) {winLevel=i; break;}

    if(winLevel==-1){
        cout<<"LOSE\n";
        return 0;
    }

    // اختيار عقدة في هذا المستوى لتعديلها
    long long target = xorLevel[winLevel];
    int chosen=-1;
    for(int i=1;i<=n;i++) if(level[i]==winLevel){
        long long newVal = h[i] ^ target;
        if(newVal < h[i]){ // يمكن تقليل الضريبة فقط
            chosen=i; h[i]=newVal; break;
        }
    }
    // إذا لم توجد عقدة يمكن تقليلها مباشرةً، نختار أي عقدة ونقللها إلى الصفر ثم نعيد حساب
    if(chosen==-1){
        for(int i=1;i<=n;i++) if(level[i]==winLevel){
            chosen=i; h[i]=0; break;
        }
    }

