#include <bits/stdc++.h>
using namespace std;

// شجرة فِنْكِ تدعم إضافة على مدى واستعلام نقطة
struct Fenwick {
    int n;
    vector<long long> bit1, bit2; // للـ range add / point query
    Fenwick(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        bit1.assign(n + 2, 0);
        bit2.assign(n + 2, 0);
    }
    // إضافة val على النطاق [l, r]
    void range_add(int l, int r, long long val) {
        internal_add(bit1, l, val);
        internal_add(bit1, r + 1, -val);
        internal_add(bit2, l, val * (l - 1));
        internal_add(bit2, r + 1, -val * r);
    }
    // استعلام قيمة العنصر عند idx
    long long point_query(int idx) const {
        return prefix_sum(bit1, idx) * idx - prefix_sum(bit2, idx);
    }
private:
    static void internal_add(vector<long long>& bit, int idx, long long val) {
        for (int i = idx; i < (int)bit.size(); i += i & -i) bit[i] += val;
    }
    static long long prefix_sum(const vector<long long>& bit, int idx) {
        long long res = 0;
        for (int i = idx; i > 0; i -= i & -i) res += bit[i];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; 
    if(!(cin >> n)) return 0;
    vector<long long> s(n+1);
    for (int i = 1; i <= n; ++i) cin >> s[i];

    Fenwick ft(n);
    // في البداية كل رقم k يضيف نفسه إلى موقعه => قيمة الاستعلام عند k هي مجموع 1..k
    for (int k = 1; k <= n; ++k) ft.range_add(k, k, k);

    vector<int> ans(n+1);
    // نملأ من اليمين إلى اليسار
    for (int i = n; i >= 1; --i) {
        long long target = s[i];
        int lo = 1, hi = n, pos = -1;
        while (lo <= hi) {
            int mid = (lo + hi) >> 1;
            long long cur = ft.point_query(mid);
            if (cur == target) {
                pos = mid; // نبحث عن أصغر موضع يحقق الشرط
                hi = mid - 1;
            } else if (cur < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        // pos الآن هو p_i
        ans[i] = pos;
        // حذف هذا الرقم من المستقبل: نطرح قيمته من كل موقع أكبر منه
        ft.range_add(pos + 1, n, -pos);
        // نجعل موقع pos غير مستخدم (نضع قيمته صفرًا)
        ft.range_add(pos, pos, -ft.point_query(pos));
    }

    for (int i = 1; i <= n; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}
