#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n; 
    vector<long long> bit;
    BIT(int n = 0) {init(n);}    
    void init(int n_) {n = n_; bit.assign(n + 1, 0);}    
    void add(int idx, long long val) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += val;
    }
    long long sum(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    // أول فهرس بحيث يكون sum(idx) >= k (k يبدأ من 1)
    int kth(long long k) const {
        int idx = 0;
        int mask = 1;
        while (mask << 1 <= n) mask <<= 1;
        for (int step = mask; step; step >>= 1) {
            int nxt = idx + step;
            if (nxt <= n && bit[nxt] < k) {
                idx = nxt;
                k -= bit[nxt];
            }
        }
        return idx + 1; // الفهرس المطلوب
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; 
    if (!(cin >> n)) return 0;
    vector<int> p(n + 1);
    vector<int> pos(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> p[i];
        pos[p[i]] = i; // موضع كل قيمة
    }

    BIT bitCnt(n), bitSum(n); // عدد العناصر ومجموع مواضعها
    long long inv = 0; // عدد الانقلابات حتى الآن (حركات لجلب القيم إلى الترتيب المتزايد)
    vector<long long> answer(n + 1);

    for (int k = 1; k <= n; ++k) {
        int idx = pos[k];
        // عدد الانقلابات التي يضيفها العنصر الجديد
        long long smaller = bitCnt.sum(idx); // عدد العناصر الموجودة قبل idx
        inv += (k - 1 - smaller);
        // نضيف العنصر إلى هياكل البيانات
        bitCnt.add(idx, 1);
        bitSum.add(idx, idx);

        // إيجاد الموضع الوسطي للـ k عنصر
        int medianPos = bitCnt.kth((k + 1) / 2);
        // عدد العناصر على اليسار من الوسيط
        long long leftCnt = bitCnt.sum(medianPos - 1);
        long long leftSum = bitSum.sum(medianPos - 1);
        // عدد العناصر على اليمين من الوسيط (بما فيها الوسيط نفسه)
        long long rightCnt = k - leftCnt;
        long long rightSum = bitSum.sum(n) - leftSum;

        // حساب عدد الحركات لجمع الأعداد في متتالية تبدأ من (medianPos - leftCnt)
        // الصيغة المستخلصة من الفرق بين المواضع المطلوبة والمواضع الفعلية
        long long targetStart = medianPos - leftCnt; // الموضع الذي يجب أن يبدأ فيه الرقم 1
        // مجموع الحركات للجهة اليسرى
        long long movesLeft = leftCnt * targetStart - leftSum + leftCnt * (leftCnt + 1) / 2;
        // مجموع الحركات للجهة اليمنى
        long long movesRight = rightSum - rightCnt * targetStart - rightCnt * (rightCnt - 1) / 2;
        long long totalMoves = movesLeft + movesRight;

        answer[k] = inv + totalMoves;
    }

    for (int k = 1; k <= n; ++k) {
        cout << answer[k] << (k == n ? '\n' : ' ');
    }
    return 0;
}
