int sz[2 * MAXN];                   // وزن كل مكوّن (عدد المتغيّرات التي يمكن اختيارها بحرية)

int find_set(int v) {
    return (parent[v] == v) ? v : parent[v] = find_set(parent[v]);
}

void unite(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a == b) return;
    // إذا كان أحد الجذور هو الصفر (العنصر المعطل) لا ندمج الوزن
    if (a == 0 || b == 0) {
        parent[a == 0 ? b : a] = 0; // الجذر غير الصفر يصبح تابعًا للصفر
        return;
    }
    // دمج عادي مع جمع الأوزان
    parent[b] = a;
    sz[a] += sz[b];
}

// تحسب عدد العمليات اللازمة للمكوّن المتعلق بالمتغيّر x (أو مكملته)
