    int fy = find_set(y);
    if (fx == 0 || fy == 0) {
        // إذا كان أحدهما معطَّلًا، نأخذ وزن المكوّن المتبقي فقط
        return sz[fx] + sz[fy];
    }
    // نختار الأصغر بين المكوّن ومكملته
    return min(sz[fx], sz[fy]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    cin >> s;
    s = " " + s; // لتصبح 1‑‑مؤشرية

    // تهيئة DSU: لكل مجموعة i يوجد عقدة i (اختيارها) وعقدة i+k (اختيارها معكوسًا)
    for (int i = 1; i <= 2 * k; ++i) {
        parent[i] = i;
        sz[i] = 1;               // كل عقدة لها وزن 1 في البداية
    }
    // العنصر 0 يمثل الحالة «معطَّلة» (متصلة بالصفر)
    parent[0] = 0;
    sz[0] = 0;

    // قراءة المجموعات وتسجيل أي مجموعة تنتمي إلى أي مصباح
    for (int i = 1; i <= k; ++i) {
        int c; cin >> c;
        while (c--) {
            int x; cin >> x;
            belong[x].push_back(i);
        }
    }

    long long answer = 0; // مجموع المساهمات الحالية
    for (int i = 1; i <= n; ++i) {
        if (belong[i].size() == 1) {
            int g = belong[i][0];
            // نزيل المساهمة القديمة للمجموعة g
            answer -= contribution(g);
            // إذا كان المصباح مضاءً نُعطِّل المكمل، وإلا نُعطِّل الأصلية
            if (s[i] == '1') {
                // نربط المكمل (g+k) بالعنصر 0
                unite(g + k, 0);
            } else {
                unite(g, 0);
            }
            // نضيف المساهمة الجديدة بعد التحديث
            answer += contribution(g);
        } else if (belong[i].size() == 2) {
            int g1 = belong[i][0];
            int g2 = belong[i][1];
            if (s[i] == '1') {
                // الحالة: المتغيّران يجب أن تكون قيمتهما متساوية
                if (find_set(g1) != find_set(g2)) {
                    answer -= contribution(g1) + contribution(g2);
                    unite(g1, g2);
                    unite(g1 + k, g2 + k);
                    answer += contribution(g1);
                }
            } else {
                // الحالة: المتغيّران يجب أن تكون قيمتهما معاكسة
                if (find_set(g1) != find_set(g2 + k)) {
                    answer -= contribution(g1) + contribution(g2);
                    unite(g1, g2 + k);
                    unite(g1 + k, g2);
                    answer += contribution(g1);
                }
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
