```cpp
#include <bits/stdc++.h>
using namespace std;

struct Minion {
    long long a, b;
    int idx; // رقم الوحش الأصلي (1‑‑‑)
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; 
    if(!(cin >> T)) return 0;
    while (T--) {
        int n, k;
        cin >> n >> k;
        vector<Minion> ms(n);
        for (int i = 0; i < n; ++i) {
            cin >> ms[i].a >> ms[i].b;
            ms[i].idx = i + 1;
        }
        // ترتيب الوحوش حسب b نزولاً (إذا تساوى b يمكن أي ترتيب)
        sort(ms.begin(), ms.end(), [](const Minion& x, const Minion& y){
            return x.b > y.b;
        });

        // DP[i][j] = أقصى مجموع باستخدام أول i وحوش واختيار j منها
        const long long NEG = -(1LL<<60);
        vector<vector<long long>> dp(n+1, vector<long long>(k+1, NEG));
        vector<vector<char>> take(n+1, vector<char>(k+1, 0)); // لتتبع الاختيار
        dp[0][0] = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = 0; j <= k; ++j) {
                // لا نأخذ الوحش i
                dp[i][j] = dp[i-1][j];
                take[i][j] = 0;
                // نأخذ الوحش i إذا كان j>0
                if (j > 0 && dp[i-1][j-1] != NEG) {
                    long long cand = dp[i-1][j-1] + ms[i-1].a + ms[i-1].b * (j-1);
                    if (cand > dp[i][j]) {
                        dp[i][j] = cand;
                        take[i][j] = 1; // أخذنا الوحش i كعنصر j في الترتيب
                    }
                }
            }
        }
        // اختيار j (≤k) الذي يعطي أقصى قيمة
        int bestJ = 0;
        for (int j = 1; j <= k; ++j) {
            if (dp[n][j] > dp[n][bestJ]) bestJ = j;
        }
        // استرجاع الوحوش المختارة (سنحصل عليها بترتيبها في الـ DP وهو نفسه ترتيب b غير المتزايد)
        vector<int> chosen;
        int i = n, j = bestJ;
        while (i > 0) {
            if (take[i][j]) {
                chosen.push_back(ms[i-1].idx); // نضيف رقم الوحش الأصلي
                --j;
            }
            --i;
        }
        // chosen الآن بترتيب عكسي (من الأخير إلى الأول)، نعيده للترتيب الصحيح
        reverse(chosen.begin(), chosen.end());

        // عدد الإجراءات هو عدد الوحوش المختارة (نستدعيهم فقط، لا ندمّر شيء)
        cout << chosen.size() << '\n';
        for (size_t p = 0; p < chosen.size(); ++p) {
            if (p) cout << ' ';
            cout << chosen[p];
        }
        if (!chosen.empty()) cout << '\n';
        else cout << '\n'; // إذا كان لا شيء نطبع سطر فارغ
    }
    return 0;
}
```
هذا البرنامج يقرأ جميع حالات الاختبار، يطبق DP بعد ترتيب الوحوش حسب b، يستخرج مجموعة الوحوش المثلى، ثم يطبع عدد الإجراءات متبوعاً بأرقام الوحوش بالترتيب الذي يضمن أقصى مجموع للطاقات. لا يلزم أي عمليات تدمير لأن عدد الوحوش المستدعاة لا يتجاوز k.

