    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long double A, B, C;
    if(!(cin >> A >> B >> C)) return 0;

    const long double EPS = 1e-12L;

    // الحالة العامة عندما يكون A = 0
    if (fabsl(A) < EPS) {
        if (fabsl(B) < EPS) {
            if (fabsl(C) < EPS) {
                // كل القيم صحيحة → عدد لا نهائي من الجذور
                cout << -1;
            } else {
                // معادلة ثابتة لا تساوي الصفر → لا جذور
                cout << 0;
            }
        } else {
            // معادلة خطية Bx + C = 0
            long double root = -C / B;
            cout << 1 << '\n';
            cout.setf(ios::fixed); cout << setprecision(10) << (double)root;
        }
        return 0;
    }

    // معادلة تربيعية
    long double D = B * B - 4.0L * A * C;
    if (D > EPS) {
        long double sqrtD = sqrtl(D);
        long double x1 = (-B - sqrtD) / (2.0L * A);
        long double x2 = (-B + sqrtD) / (2.0L * A);
        if (x1 > x2) swap(x1, x2);
        cout << 2 << '\n';
        cout.setf(ios::fixed); cout << setprecision(10) << (double)x1 << '\n' << (double)x2;
    } else if (fabsl(D) <= EPS) {
        long double x = -B / (2.0L * A);
        cout << 1 << '\n';
        cout.setf(ios::fixed); cout << setprecision(10) << (double)x;
    } else {
        cout << 0;
