int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, r, c;
    if(!(cin>>n>>r>>c)) return 0;
    vector<string> words(n+1);
    for(int i=1;i<=n;i++) cin>>words[i];

    // طول كل كلمة
    vector<int> len(n+1);
    for(int i=1;i<=n;i++) len[i]=words[i].size();

    // f[i] = أول كلمة لا يمكن وضعها في السطر الأول إذا بدأنا من i
    vector<int> f(n+2);
    int right=1, curLen=-1; // -1 لأن أول كلمة لا تحتاج مساحة قبلها
    for(int i=1;i<=n;i++){
        while(right<=n && curLen+1+len[right]<=c){
            curLen+=1+len[right];
            ++right;
        }
        f[i]=right; // right هو أول كلمة لا تُستوعب
        // نزيل كلمة i من النافذة
        if(right==i) { // إذا كانت النافذة فارغة
            ++right;
        } else {
            curLen-=(1+len[i]);
        }
    }
    f[n+1]=n+1;

    // رفع الأس (binary lifting) حتى نصل إلى r سطرًا
    const int LOG=20; // لأن r ≤ 10^6
    vector<vector<int>> up(LOG, vector<int>(n+2));
    for(int i=1;i<=n+1;i++) up[0][i]=f[i];
    for(int k=1;k<LOG;k++)
        for(int i=1;i<=n+1;i++)
            up[k][i]=up[k-1][ up[k-1][i] ];

    // حساب عدد الكلمات التي يمكن وضعها بدءًا من كل i
    int bestStart=1, bestCnt=0;
    for(int i=1;i<=n;i++){
        int pos=i;
        int steps=r;
        for(int k=0; steps; k++){
            if(steps&1) pos=up[k][pos];
            steps>>=1;
        }
        int cnt=pos-i; // عدد الكلمات التي سُتطبع
        if(cnt>bestCnt){
            bestCnt=cnt;
            bestStart=i;
        }
    }

    // طباعة النتيجة
    int idx=bestStart;
    for(int line=0; line<r && idx<=n; ++line){
        int lineLen=0;
        bool first=true;
        while(idx<=n && lineLen + (first?0:1) + len[idx] <= c){
            if(!first) {
                cout<<' ';
                lineLen+=1;
            }
            cout<<words[idx];
            lineLen+=len[idx];
            ++idx;
            first=false;
        }
        if(line!=r-1) cout<<'\n';
    }
    return 0;
}
