#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n = 0) { init(n); }
    void init(int n_) { n = n_; bit.assign(n + 1, 0); }
    void add(int idx, long long delta) {
        for (; idx <= n; idx += idx & -idx) bit[idx] += delta;
    }
    long long sumPrefix(int idx) const {
        long long res = 0;
        for (; idx > 0; idx -= idx & -idx) res += bit[idx];
        return res;
    }
    long long rangeSum(int l, int r) const { // inclusive
        if (l > r) return 0;
        return sumPrefix(r) - sumPrefix(l - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k, a, b, q;
    if (!(cin >> n >> k >> a >> b >> q)) return 0;

    vector<int> orders(n + 1, 0);          // عدد الطلبات لكل يوم
    Fenwick bitB(n), bitA(n);              // bitB تخزن min(orders, b) ، bitA تخزن min(orders, a)

    while (q--) {
        int type; cin >> type;
        if (type == 1) {
            int d, x; cin >> d >> x;
            // تحديث عدد الطلبات في اليوم d
            int old = orders[d];
            int neu = old + x;
            orders[d] = neu;
            // حساب القيم القديمة والجديدة للحدين
            long long oldB = min(old, b);
            long long newB = min(neu, b);
            long long oldA = min(old, a);
            long long newA = min(neu, a);
            // تعديل الشجرتين
            bitB.add(d, newB - oldB);
            bitA.add(d, newA - oldA);
        } else { // type == 2
            int p; cin >> p;
            // الأيام قبل الصيانة: 1 .. p-1 (تُستَخدم السعة b)
            long long before = bitB.rangeSum(1, p - 1);
            // الأيام بعد الصيانة: p+k .. n (تُستَخدم السعة a)
            long long after = bitA.rangeSum(p + k, n);
            cout << before + after << '\n';
        }
    }
    return 0;
}
