public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        // استخراج الأجزاء بين العلامات والمسافات
        String[] parts = line.split(" ");
        List<Boolean> isPlus = new ArrayList<>(); // true إذا كان المتغير يسبق علامة جمع أو هو أول متغير
        int n = 0; // القيمة بعد علامة =
        int plusCount = 0, minusCount = 0;
        // نمر على الرموز لتحديد نوع كل علامة استفهام
        boolean first = true;
        for (int i = 0; i < parts.length; i++) {
            String token = parts[i];
            if (token.equals("?")) {
                if (first) {
                    isPlus.add(true);
                    plusCount++;
                    first = false;
                } else {
                    // النوع يحدده الرمز السابق (+ أو -)
                    String prev = parts[i - 1];
                    if (prev.equals("+")) {
                        isPlus.add(true);
                        plusCount++;
                    } else if (prev.equals("-")) {
                        isPlus.add(false);
                        minusCount++;
                    }
                }
            } else if (token.equals("=")) {
                n = Integer.parseInt(parts[i + 1]);
                break;
            }
        }
        // حساب الحد الأدنى والحد الأقصى للمجموع الممكن
        long minSum = (long)plusCount * 1 - (long)minusCount * n;
        long maxSum = (long)plusCount * n - (long)minusCount * 1;
        if (n < minSum || n > maxSum) {
            System.out.println("Impossible");
            return;
        }
        // نبدأ بالقيم القصوى للعلامات الموجبة والقيم الدنيا للعلامات السالبة
        int[] plusVals = new int[plusCount];
        int[] minusVals = new int[minusCount];
        Arrays.fill(plusVals, n);
        Arrays.fill(minusVals, 1);
        long current = maxSum; // المجموع الحالي
        long need = current - n; // مقدار الفارق الذي يجب تقليله
        // أولاً نخفض قيم العلامات الموجبة قدر الإمكان
        for (int i = 0; i < plusCount && need > 0; i++) {
            long canReduce = plusVals[i] - 1; // أقصى مقدار يمكن خفضه
            long delta = Math.min(canReduce, need);
            plusVals[i] -= (int)delta;
            need -= delta;
        }
        // إذا بقي فاصل نرفع قيم العلامات السالبة
        for (int i = 0; i < minusCount && need > 0; i++) {
            long canIncrease = n - minusVals[i];
            long delta = Math.min(canIncrease, need);
            minusVals[i] += (int)delta;
            need -= delta;
        }
        // الآن نطبع النتيجة
        System.out.println("Possible");
        StringBuilder sb = new StringBuilder();
        int pIdx = 0, mIdx = 0;
        boolean expectPlus = true; // العلامة الأولى دائمًا جمع
        for (int i = 0; i < parts.length; i++) {
            String token = parts[i];
            if (token.equals("?")) {
                if (expectPlus) {
                    sb.append(plusVals[pIdx++]);
                } else {
                    sb.append(minusVals[mIdx++]);
                }
                sb.append(' ');
            } else if (token.equals("+")) {
                sb.append("+ ");
                expectPlus = true;
            } else if (token.equals("-")) {
                sb.append("- ");
                expectPlus = false;
            } else if (token.equals("=")) {
                sb.append("= ");
                sb.append(n);
                break;
            }
        }
        System.out.println(sb.toString().trim());
    }
}
