#include <bits/stdc++.h>
using namespace std;

struct DSUParity {
    vector<int> parent, sz, parity; // parity: 0 إذا نفس اللون مع الجذر، 1 إذا لون مختلف
    DSUParity(int n = 0) { init(n); }
    void init(int n) {
        parent.resize(n);
        sz.assign(n, 1);
        parity.assign(n, 0);
        iota(parent.begin(), parent.end(), 0);
    }
    // find مع تحديث parity إلى الجذر
    pair<int,int> find(int x) {
        if (parent[x] == x) return {x, 0};
        auto res = find(parent[x]);
        parent[x] = res.first;
        parity[x] ^= res.second;
        return {parent[x], parity[x]};
    }
    // نجمع x و y مع فرضية أن لونهما مختلف (edge يجب أن يقطع بين القطعتين)
    // تُرجع false إذا كان هناك تعارض (أي أن x و y يجب أن يكونا في نفس اللون)
    bool unite(int x, int y) {
        auto fx = find(x);
        auto fy = find(y);
        int rx = fx.first, px = fx.second;
        int ry = fy.first, py = fy.second;
        if (rx == ry) {
            // إذا كان اللون المتوقع مختلفاً (px ^ py) != 1 فهناك تعارض
            return (px ^ py) == 1; // إذا كان صحيحاً لا يوجد تعارض
        }
        // نريد أن يكون px ^ parity_between ^ py == 1
        // حيث parity_between = 1 (نريد ألوان مختلفة)
        // لذا نضبط parity للـ root الأصغر لتحقق هذا الشرط
        if (sz[rx] < sz[ry]) {
            swap(rx, ry);
            swap(px, py);
        }
        parent[ry] = rx;
        // parity[ry] هو الفرق بين لون ry ولون rx بعد الدمج
        // نحتاج: px ^ parity[ry] ^ py = 1  => parity[ry] = px ^ py ^ 1
        parity[ry] = px ^ py ^ 1;
        sz[rx] += sz[ry];
        return true;
    }
};

struct Edge {
    int u, v;
    int w;
    int idx; // رقم الطريق الأصلي (1‑‑‑مؤشر)
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    if (!(cin >> n >> m >> q)) return 0;
    vector<Edge> edges(m);
    for (int i = 0; i < m; ++i) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
        --edges[i].u; --edges[i].v; // صفر‑‑‑مؤشر
        edges[i].idx = i + 1; // حفظ الرقم الأصلي للسهولة في المقارنة
    }
    // ترتيب تنازلي حسب الوزن
    vector<int> order(m);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return edges[a].w > edges[b].w; });

    while (q--) {
        int l, r; // نطاق الطرق المتبقية (1‑‑‑مؤشر)
        cin >> l >> r;
        DSUParity dsu(n);
        int answer = -1;
        for (int id : order) {
            int roadNum = edges[id].idx; // رقم الطريق الأصلي
            if (roadNum < l || roadNum > r) continue; // غير ضمن النطاق
            // نحاول ربط u مع v بحيث يكونا في قطعتين مختلفتين
            if (!dsu.unite(edges[id].u, edges[id].v)) {
                answer = edges[id].w;
                break; // أول وزن يسبب تعارض هو الحد الأدنى المطلوب
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
