int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n), b(n);
    int totalA = 0, totalB = 0;
    for (int i = 0; i < n; ++i) { cin >> a[i]; totalA += a[i]; }
    for (int i = 0; i < n; ++i) { cin >> b[i]; totalB += b[i]; }

    const int INF = 1e9;
    // dp[s] = {min bottles, max soda already inside those bottles}
    vector<pair<int,int>> dp(totalB + 1, {INF, -INF});
    dp[0] = {0, 0};

    for (int i = 0; i < n; ++i) {
        for (int s = totalB - b[i]; s >= 0; --s) {
            if (dp[s].first == INF) continue; // غير reachable
            int ns = s + b[i];
            int nb = dp[s].first + 1;
            int na = dp[s].second + a[i];
            if (nb < dp[ns].first) {
                dp[ns] = {nb, na};
            } else if (nb == dp[ns].first && na > dp[ns].second) {
                dp[ns].second = na;
            }
        }
    }

    int bestK = INF;
    int bestInside = -INF;
    for (int s = totalA; s <= totalB; ++s) {
        if (dp[s].first == INF) continue;
        if (dp[s].first < bestK) {
            bestK = dp[s].first;
            bestInside = dp[s].second;
        } else if (dp[s].first == bestK && dp[s].second > bestInside) {
            bestInside = dp[s].second;
        }
    }

    int t = totalA - bestInside; // الوقت هو الصودا التي يجب نقلها
    cout << bestK << ' ' << t << '\n';
    return 0;
}
