public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // قراءة الزوج الأول
        String a = fs.next();
        String b = fs.next();
        out.println(a + " " + b);

        int n = fs.nextInt();
        for (int i = 0; i < n; i++) {
            String killed = fs.next();
            String newcomer = fs.next();
            if (killed.equals(a)) {
                a = newcomer; // استبدال المتغيّر a
            } else {
                b = newcomer; // استبدال المتغيّر b (المقتول لا يمكن أن يكون غيرهما)
            }
            out.println(a + " " + b);
        }
        out.flush();
    }

    // قارئ سريع للمدخلات
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        FastScanner(InputStream in) { this.in = in; }
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        private boolean isSpace(int c) { return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1; }
