    vector<Block> blocks;          // الكتل الحالية (موجودة فقط إذا لم تُمحى)
    int next_id = 1;               // المعرف التالي للكتل الناجحة

    for (int i = 0; i < t; ++i) {
        string cmd;
        cin >> cmd;
        if (cmd == "alloc") {
            int n; cin >> n;
            // البحث عن أول فجوة كافية من البداية
            int pos = 0; // موقع الفجوة المحتملة
            bool placed = false;
            // نرتب الكتل حسب موقعها لتسهيل الفحص (الترتيب يُحافظ عليه دائماً)
            sort(blocks.begin(), blocks.end(), [](const Block& a, const Block& b){return a.start < b.start;});
            for (const auto& blk : blocks) {
                if (blk.start - pos >= n) { // الفجوة بين pos و blk.start كافية
                    blocks.push_back({pos, n, next_id});
                    cout << next_id << '\n';
                    ++next_id;
                    placed = true;
                    break;
                }
                pos = blk.start + blk.len; // الانتقال إلى بعد نهاية الكتلة الحالية
            }
            if (!placed) {
                if (m - pos >= n) { // الفجوة الأخيرة في نهاية الذاكرة
                    blocks.push_back({pos, n, next_id});
                    cout << next_id << '\n';
                    ++next_id;
                } else {
                    cout << "NULL" << '\n';
                }
            }
        } else if (cmd == "erase") {
            int x; cin >> x;
            bool found = false;
            for (auto it = blocks.begin(); it != blocks.end(); ++it) {
                if (it->id == x) {
                    blocks.erase(it);
                    found = true;
                    break;
                }
            }
            if (!found) {
                cout << "ILLEGAL_ERASE_ARGUMENT" << '\n';
            }
        } else if (cmd == "defragment") {
            // ترتيب الكتل حسب موقعها ثم نقلها إلى أقرب موضع ممكن
            sort(blocks.begin(), blocks.end(), [](const Block& a, const Block& b){return a.start < b.start;});
            int cur = 0; // الموضع التالي المتاح
            for (auto &blk : blocks) {
                blk.start = cur;
                cur += blk.len;
            }
        }
    }
    return 0;
}
