```java
import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream INPUT = System.in;
    private static final byte[] buffer = new byte[1 << 16];
    private static int ptr = 0, len = 0;

    private static int read() throws IOException {
        if (ptr >= len) {
            len = INPUT.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    private static int nextInt() throws IOException {
        int c, sign = 1, val = 0;
        do { c = read(); } while (c <= ' ' && c != -1);
        if (c == '-') { sign = -1; c = read(); }
        while (c > ' ') {
            val = val * 10 + (c - '0');
            c = read();
        }
        return val * sign;
    }

    public static void main(String[] args) throws Exception {
        int n = nextInt();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = nextInt();

        // حساب الانحراف للإزاحة 0
        long cur = 0;
        for (int i = 0; i < n; i++) cur += Math.abs(p[i] - (i + 1));

        // diff[k] = التغير في الانحراف عندما ننتقل من الإزاحة k إلى k+1
        long[] diff = new long[n];
        // لكل عنصر نحسب متى يمر عبر نقطة الانعطاف التي يغيّر فيها إشارة الفارق
        for (int i = 0; i < n; i++) {
            int val = p[i];
            // الموضع الحالي للعنصر عند الإزاحة k هو (i + k) % n + 1
            // نحتاج إلى معرفة القيم k التي يصبح فيها val > pos أو العكس.
            // عندما يصبح pos = val فإن الفارق يساوي 0 ويتغيّر الاتجاه.
            // الموضع يساوي val عندما: (i + k) % n + 1 = val
            // أي k ≡ (val - 1 - i) (mod n)
            int k0 = (val - 1 - i) % n;
            if (k0 < 0) k0 += n; // أول إزاحة تجعل العنصر في موضعه الصحيح

            // قبل k0 يكون الفارق يزداد كل خطوة (لأن pos يبعد عن val بمقدار 1)
            // بعد k0 يبدأ الفارق يتناقص كل خطوة.
            // لذلك نضيف +1 إلى diff[0] (بداية الزيادة) ونضيف -2 عند k0 (تبديل الاتجاه) ثم +1 عند (k0+1) لتعود للزيادة بعد دورة كاملة.
            diff[0] += 1; // كل إزاحة تزيد الفارق بواحد في البداية
            diff[k0] -= 2; // عند k0 يتغير الاتجاه، لذا نطرح 2
            // بعد إكمال دورة كاملة (k0 + n) لا نحتاج لتعديل لأننا نعمل على دورة بطول n فقط.
        }

        // الآن نحسب الانحرافات المتتالية باستخدام diff
        long best = cur;
        int bestShift = 0;
        long acc = 0; // مجموع التغييرات حتى الآن
        for (int k = 0; k < n - 1; k++) { // ننتقل من الإزاحة k إلى k+1
            acc += diff[k];
            cur += acc; // الانحراف للإزاحة k+1
            if (cur < best) {
                best = cur;
                bestShift = k + 1;
            }
        }

        System.out.println(best + " " + bestShift);
    }
}
```
هذا البرنامج يقرأ permutation، يحسب الانحراف للإزاحة صفر، ثم يبني مصفوفة diff التي تمثّل التغير في الانحراف عند كل خطوة إزاحة. بعد ذلك يجري تراكمًا لتحديد أصغر انحراف وإزاحته. التعقيد الزمني O(n) والذاكرة O(n) فقط، وهو مناسب للحد n ≤ 10⁶.

