```cpp
#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int n;
vector<int64> b, a;
vector<int> parent;
vector<int64> k; // معامل التحويل من الأب إلى الابن
vector<vector<int>> children;

bool ok = true;

i128 dfs(int u) {
    // الفرق الأولي في العقدة u
    i128 diff = (i128)b[u] - (i128)a[u]; // إيجابي = فائض، سالب = عجز
    for (int v : children[u]) {
        i128 childDiff = dfs(v);
        if (!ok) return 0; // إذا اكتشفنا فشل مسبقاً نوقف الحساب
        if (childDiff < 0) {
            // عجز في الابن يحتاج تحويل من الأب بمعامل k[v]
            diff += childDiff * (i128)k[v]; // k[v] * (سالب) يبقى سالباً
        } else {
            // فائض في الابن لا يمكن إرجاعه للأب (التحويل من الابن إلى الأب هو 1:1)
            // لذا نضيفه مباشرة إلى diff (يمكن تركه في الابن)
            diff += childDiff;
        }
    }
    // إذا كان الفرق في العقدة سالباً جداً (أقل من -1e30 مثلاً) قد يتجاوز السعة،
    // لكن باستخدام i128 لا توجد مشكلة في النطاق المطلوب (≈10^21).
    return diff;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n)) return 0;
    b.assign(n + 1, 0);
    a.assign(n + 1, 0);
    parent.assign(n + 1, 0);
    k.assign(n + 1, 1);
    children.assign(n + 1, {});

    for (int i = 1; i <= n; ++i) cin >> b[i];
    for (int i = 1; i <= n; ++i) cin >> a[i];

    for (int i = 2; i <= n; ++i) {
        int x; int64 kk; // x هو الأب، kk هو معامل التحويل من الأب إلى i
        cin >> x >> kk;
        parent[i] = x;
        k[i] = kk;
        children[x].push_back(i);
    }

    i128 rootDiff = dfs(1);
    if (!ok) {
        cout << "NO\n";
        return 0;
    }
    // إذا كان الفرق في الجذر سالباً يعني لا يمكن تغطية العجز الكلي
    if (rootDiff < 0) cout << "NO\n";
    else cout << "YES\n";
    return 0;
}
```
هذه الشيفرة تتبع نفس الفكرة الأصلية لكن:
- تستخدم نوع i128 لتجنب أي تجاوز للمدى.
- تصحّح منطق الجمع بحيث يُضاعف العجز بمعامل k فقط، بينما يُجمع الفائض كما هو.
- تُعيد النتيجة النهائية بناءً على الفرق في الجذر فقط، وهو ما يكفي لأن جميع العجزات تم تعويضها خلال عملية الـ DFS.
- تُستبدل عمليات الخروج الفورية بـ متغيّر `ok` لتكون أكثر وضوحاً.

