            if (p == 0) root = i; // رأس الشجرة
            else tree[p].add(i);
        }
        if (n % 2 == 0) {
            out.println("NO");
            out.flush();
            return;
        }
        out.println("YES");
        subSize = new int[n + 1];
        dfsSize(root);
        dfsPrint(root);
        out.print(answer.toString());
