        for (int v : tree[u]) {
            dfsSize(v);
            subSize[u] += subSize[v];
        }
    }

    // طباعة ترتيب التدمير وفق القاعدة المذكورة
    static void dfsPrint(int u) {
        // أولاً الفروع ذات الحجم الزوجي
        for (int v : tree[u]) {
