int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    if (!(cin >> n >> m >> k)) return 0;
    vector<int> blocked(n, 0);
    for (int i = 0; i < m; ++i) {
        int x; cin >> x;
        blocked[x] = 1;
    }
    vector<long long> cost(k + 1);
    for (int i = 1; i <= k; ++i) cin >> cost[i];

    // إذا كان الموضع 0 محجوزاً لا يمكن البدء أبداً
    if (blocked[0]) {
        cout << -1 << '\n';
        return 0;
    }

    // prefix[i] = أكبر موقع غير محجوز ≤ i (أو -1 إذا لا يوجد)
    vector<int> prefix(n);
    for (int i = 0; i < n; ++i) {
        if (!blocked[i]) prefix[i] = i;
        else prefix[i] = (i == 0 ? -1 : prefix[i - 1]);
    }

    const long long INF = (1LL << 60);
    long long answer = INF;

    // نجرب كل قوة l من 1 إلى k
    for (int l = 1; l <= k; ++l) {
        long long lamps = 0;          // عدد المصابيح المستخدمة
        int covered = 0;              // أقصى نقطة مغطاة حتى الآن (نقطة البداية غير مغطاة هي covered)
        bool possible = true;
        while (covered < n) {
            // إذا كان بإمكان مصباح واحد من القوة l أن يغطّي ما تبقى
            if (covered + l >= n) {
                ++lamps;
                covered = n; // انتهى
                break;
            }
            int pos = prefix[covered + l]; // أبعد موقع غير محجوز ≤ covered+l
            if (pos <= covered) { // لا يوجد موقع يتيح التقدم
                possible = false;
                break;
            }
            // نضع المصباح في pos، وبالتالي يغطي حتى pos + l
            covered = pos + l;
            ++lamps;
        }
        if (possible) {
            answer = min(answer, lamps * cost[l]);
        }
    }

    if (answer == INF) cout << -1 << '\n';
    else cout << answer << '\n';
    return 0;
}
