# قراءة البيانات
M, N = map(int, input().split())
board = []
for _ in range(M):
    board.append(list(map(int, input().split())))

# دالة تتحقق إذا كان هناك مصفوفة 2×2 كلها رؤوس
def has_all_one(b):
    for i in range(M-1):
        for j in range(N-1):
            if b[i][j] == b[i][j+1] == b[i+1][j] == b[i+1][j+1] == 1:
                return True
    return False

# إذا كان الشرط متحققاً من البداية
if has_all_one(board):
    print(0)
    exit()

# تحويل مصفوفة إلى سلسلة لتسهيل تخزين الحالة في الـ set
def encode(b):
    return ''.join(str(cell) for row in b for cell in row)

# عكس قيم داخل مصفوفة فرعية محددة
def flip(b, r1, c1, r2, c2):
    new_b = copy.deepcopy(b)
    for i in range(r1, r2+1):
        for j in range(c1, c2+1):
            new_b[i][j] ^= 1  # عكس القيمة
    return new_b

# جميع المربعات الفرعية التي حجم أحد أبعادها أكبر من 1
sub_rects = []
for r1 in range(M):
    for r2 in range(r1, M):
        for c1 in range(N):
            for c2 in range(c1, N):
                if max(r2-r1+1, c2-c1+1) > 1:
                    sub_rects.append((r1, c1, r2, c2))

# بحث بالعرض لإيجاد أقل عدد خطوات (0،1،2 أو -1)
visited = set()
queue = deque()
start_state = encode(board)
queue.append((board, 0))
visited.add(start_state)
answer = -1
while queue:
    cur_board, steps = queue.popleft()
    if steps >= 2:  # لا نحتاج للبحث أبعد من خطوتين حسب التحليل
        continue
    for r1, c1, r2, c2 in sub_rects:
        nxt = flip(cur_board, r1, c1, r2, c2)
        enc = encode(nxt)
        if enc in visited:
            continue
        if has_all_one(nxt):
            answer = steps + 1
            queue.clear()
            break
        visited.add(enc)
        queue.append((nxt, steps + 1))
    if answer != -1:
        break

