import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }

    static List<Integer>[] tree;
    static int[] subSize;
    static StringBuilder answer = new StringBuilder();

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        // إذا كان عدد الرؤوس زوجيًا لا يمكن تدميره بالكامل
        if (n % 2 == 0) {
            System.out.println("NO");
            return;
        }
        // بناء الشجرة من الوالد إلى الابن
        tree = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) tree[i] = new ArrayList<>();
        int root = 1; // افتراضياً
        for (int i = 1; i <= n; i++) {
            int p = fs.nextInt();
            if (p == 0) {
                root = i; // هذا هو الجذر
            } else {
                tree[p].add(i);
            }
        }
        subSize = new int[n + 1];
        dfsSize(root);
        answer.append("YES\n");
        dfsOrder(root);
        System.out.print(answer.toString());
    }

    // حساب حجم كل شجرة فرعية
    static void dfsSize(int u) {
        subSize[u] = 1;
        for (int v : tree[u]) {
            dfsSize(v);
            subSize[u] += subSize[v];
        }
    }

    // طباعة ترتيب التدمير وفق القاعدة المذكورة
    static void dfsOrder(int u) {
        // أولاً الفروع ذات الحجم الزوجي
        for (int v : tree[u]) {
            if (subSize[v] % 2 == 0) dfsOrder(v);
        }
        // ثم حذف الرأس الحالي
        answer.append(u).append('\n');
        // ثم الفروع ذات الحجم الفردي
        for (int v : tree[u]) {
            if (subSize[v] % 2 != 0) dfsOrder(v);
        }
    }
}
