import sys
from collections import deque

def read_input():
    data = sys.stdin.read().strip().split()
    if not data:
        return 0, 0, []
    it = iter(data)
    m = int(next(it))
    n = int(next(it))
    grid = [int(next(it)) for _ in range(m * n)]
    return m, n, grid

def to_mask(grid):
    mask = 0
    for i, val in enumerate(grid):
        if val == 1:
            mask |= 1 << i
    return mask

def has_all_one_square(mask, m, n):
    # نفحص كل موقع يمكن أن يبدأ منه مربع 2×2
    for i in range(m - 1):
        for j in range(n - 1):
            idx = i * n + j
            # مواقع الخانات الأربعة في المربع
            b0 = (mask >> idx) & 1
            b1 = (mask >> (idx + 1)) & 1
            b2 = (mask >> (idx + n)) & 1
            b3 = (mask >> (idx + n + 1)) & 1
            if b0 and b1 and b2 and b3:
                return True
    return False

def generate_flip_masks(m, n):
    masks = []
    for h in range(1, m + 1):
        for w in range(1, n + 1):
            if max(h, w) == 1:
                continue  # يجب أن يكون أحد الأبعاد أكبر من 1
            for i in range(m - h + 1):
                for j in range(n - w + 1):
                    mask = 0
                    for di in range(h):
                        for dj in range(w):
                            pos = (i + di) * n + (j + dj)
                            mask ^= 1 << pos
                    masks.append(mask)
    return masks

def bfs(initial_mask, m, n, flip_masks):
    if has_all_one_square(initial_mask, m, n):
        return 0
    visited = {initial_mask}
    q = deque([(initial_mask, 0)])
    while q:
        cur, steps = q.popleft()
        for fmask in flip_masks:
            nxt = cur ^ fmask
            if nxt in visited:
                continue
            if has_all_one_square(nxt, m, n):
                return steps + 1
            visited.add(nxt)
            q.append((nxt, steps + 1))
    return -1

def main():
    m, n, grid = read_input()
    if m == 0:
        return
    init_mask = to_mask(grid)
    flip_masks = generate_flip_masks(m, n)
    ans = bfs(init_mask, m, n, flip_masks)
    print(ans)

if __name__ == "__main__":
    main()
