            System.out.println(cur.toString());
            return;
        }
        // أولاً نجرب كل الحروف التي استُخدمت مسبقًا (من 'a' إلى nextChar-1)
        for (char c = 'a'; c < nextChar; c++) {
            cur.append(c);
            dfs(pos + 1);
            cur.setLength(cur.length() - 1);
        }
        // ثم نجرب إدخال حرف جديد إذا كان لا يزال هناك مساحة للأحرف
        if (nextChar <= 'z') { // الحد الأقصى للإنجليزية الصغيرة
            char newC = nextChar;
            nextChar++; // نحدّث الحرف التالي المتاح
            cur.append(newC);
            dfs(pos + 1);
            cur.setLength(cur.length() - 1);
            nextChar--; // نرجع التحديث بعد الرجوع من الاستدعاء
        }
    }
}
