    for (int i = 2; i <= N; ++i) {
        if (broken[i]) {
            dp[i] = 0;            // لا يمكن الوقوف على درجة مكسورة
        } else {
            dp[i] = (dp[i-1] + dp[i-2]) % MOD;
        }
    }
    cout << dp[N] % MOD << '\n';
    return 0;
}
