#include <bits/stdc++.h>
using namespace std;
using ll = long long;

struct Edge {
    int u, v;
    ll w;
    bool operator<(const Edge& other) const { return w < other.w; }
};

const ll INF = (ll)4e18;

int n; ll D;
vector<ll> A;               // A[i] قيم حجم المدن (1‑‑مؤشر)
vector<Edge> edges;         // قائمة الحواف التي قد تكون في MST

// ---------- توليد الحواف باستخدام تقسيم‑و‑غزو ----------
void build(int l, int r) {
    if (l >= r) return;
    int m = (l + r) >> 1;

    // البحث عن العنصر في النصف الأيسر يعطي أصغر (A[i] - D*i)
    ll bestLeft = INF; int posLeft = -1;
    for (int i = l; i <= m; ++i) {
        ll val = A[i] - D * i;
        if (val < bestLeft) { bestLeft = val; posLeft = i; }
    }
    // ربط كل عنصر في النصف الأيمن بأفضل عنصر في اليسار
    for (int i = m + 1; i <= r; ++i) {
        ll w = A[i] + A[posLeft] + D * (i - posLeft);
        edges.push_back({posLeft, i, w});
    }

    // الآن نبحث عن العنصر في النصف الأيمن يعطي أصغر (A[i] + D*i)
    ll bestRight = INF; int posRight = -1;
    for (int i = m + 1; i <= r; ++i) {
        ll val = A[i] + D * i;
        if (val < bestRight) { bestRight = val; posRight = i; }
    }
    // ربط كل عنصر في النصف الأيسر بأفضل عنصر في اليمين
    for (int i = l; i <= m; ++i) {
        ll w = A[i] + A[posRight] + D * (posRight - i);
        edges.push_back({i, posRight, w});
    }

    // استدعاء فرعي للجزئين
    build(l, m);
    build(m + 1, r);
}

// ---------- بنية اتحاد‑إيجاد (DSU) ----------
struct DSU {
    vector<int> parent, rankv;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        parent.resize(n + 1);
        rankv.assign(n + 1, 0);
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }
    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (rankv[a] < rankv[b]) swap(a, b);
        parent[b] = a;
        if (rankv[a] == rankv[b]) ++rankv[a];
        return true;
    }
};

// ---------- خوارزمية كروسكال ----------
ll kruskal() {
    sort(edges.begin(), edges.end());
    DSU dsu(n);
    ll ans = 0;
    int taken = 0;
    for (const auto& e : edges) {
        if (dsu.unite(e.u, e.v)) {
            ans += e.w;
            if (++taken == n - 1) break; // تم الحصول على شجرة تغطي جميع المدن
        }
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> D)) return 0;
    A.assign(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        cin >> A[i];
    }

    edges.reserve((size_t)n * 20); // تقدير سعة لتقليل عمليات الإعادة
    build(1, n);
    cout << kruskal() << '\n';
    return 0;
}
