#include <bits/stdc++.h>
using namespace std;

// ---------- هيكلية Union‑Find ----------
struct DSU {
    vector<int> p, sz;
    DSU(int n = 0) { init(n); }
    void init(int n) { p.resize(n); sz.assign(n,1); iota(p.begin(), p.end(), 0); }
    int find(int x){ return p[x]==x? x : p[x]=find(p[x]); }
    bool unite(int a,int b){
        a=find(a); b=find(b);
        if(a==b) return false;
        if(sz[a]<sz[b]) swap(a,b);
        p[b]=a; sz[a]+=sz[b];
        return true;
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N,M; 
    if(!(cin>>N>>M)) return 0;
    DSU dsu(N);
    vector<pair<int,int>> arcs;               // الحواف الموجهة
    vector<vector<pair<int,int>>> adj(N);     // الرسم غير الموجه (بعد دمج المكوّنات)

    for(int i=0;i<M;i++){
        int x,y,t; cin>>x>>y>>t; --x; --y;
        if(t==1){ // حافة موجهة
            arcs.emplace_back(x,y);
        }else{   // حافة غير موجهة
            if(dsu.find(x)==dsu.find(y)){
                cout<<"Infinite\n"; return 0; // دورة غير موجهة
            }
            dsu.unite(x,y);
            // نضيف الحافة غير الموجهة للتمثيل المؤقت (سنستعملها لاحقًا فقط لتحديد درجات العقد)
            adj[x].push_back({y,-1});
            adj[y].push_back({x,-1});
        }
    }

    // ---------- بناء الرسم الموجه بين المكوّنات ----------
    vector<vector<int>> dag(N);
    vector<int> indeg(N,0);
    for(auto &e: arcs){
        int u = dsu.find(e.first);
        int v = dsu.find(e.second);
        if(u==v){ // دورة موجهة داخل نفس المكوّن
            cout<<"Infinite\n"; return 0;
        }
        dag[u].push_back(v);
        indeg[v]++;
    }

    // ---------- ترتيب طوبولوجي ----------
    queue<int> q;
    for(int i=0;i<N;i++) if(dsu.find(i)==i && indeg[i]==0) q.push(i);
    vector<int> topo;
    while(!q.empty()){
        int u=q.front(); q.pop();
        topo.push_back(u);
        for(int v: dag[u]) if(--indeg[v]==0) q.push(v);
    }
    // إذا لم تُزر جميع المكوّنات يعني وجود دورة موجهة
    int comps=0; for(int i=0;i<N;i++) if(dsu.find(i)==i) comps++;
    if((int)topo.size()!=comps){
        cout<<"Infinite\n"; return 0;
    }

    // ---------- DP لحساب أطول مسار ----------
    const int NEG = -1e9; // قيمة سلبية تمثل "غير موجود"
    vector<int> dp(N, NEG); // dp[u] = أطول مسار يبدأ من المكوّن u
    // نمر على الترتيب العكسي لضمان حساب القيم للمتابعين أولاً
    for(int i=topo.size()-1;i>=0;--i){
        int u = topo[i];
        dp[u] = 0; // المسار الذي لا يمر بأي حافة يساوي صفر
        for(int v: dag[u]){
            dp[u] = max(dp[u], dp[v] + 1);
        }
    }
    int answer = 0;
    for(int i=0;i<N;i++) if(dsu.find(i)==i) answer = max(answer, dp[i]);
    cout<<answer<<"\n";
    return 0;
}
