#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int64 INF64 = (int64)4e18; // أكبر قيمة ممكنة لتقليل overflow

// ضرب آمن مع كشف overflow (يعيد INF إذا تجاوز الحد)
int64 mul_sat(int64 a, int64 b) {
    if (a == 0 || b == 0) return 0;
    if (a > INF64 / b) return INF64;
    return a * b;
}

// حساب a^k مع كشف overflow (يعيد INF إذا تجاوز الحد)
int64 pow_sat(int64 a, int64 k) {
    int64 res = 1;
    while (k) {
        if (k & 1) res = mul_sat(res, a);
        if (res == INF64) return INF64;
        a = mul_sat(a, a);
        if (a == INF64) return INF64;
        k >>= 1;
    }
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m, A, B, P, Q;
    if(!(cin >> n >> m >> A >> B >> P >> Q)) return 0;

    // إذا كان a أو b يساوي 1 فالقوة لا تتغير بعد أول خطوة
    vector<int64> tickets;
    for(int64 k = 0; k < n; ++k){
        int64 termA = mul_sat(P, pow_sat(A, k));
        int64 termB = mul_sat(Q, pow_sat(B, k));
        if(termA == INF64 || termB == INF64) break; // تجاوز الحد
        int64 cur = termA + termB;
        if(cur > m && tickets.size()>0 && cur - m > tickets.back()) {
            // إذا تجاوزنا m بفارق كبير لا فائدة من إضافة قيم أكبر
            break;
        }
        tickets.push_back(cur);
        if(cur > m && cur - m > m) break; // حماية إضافية
    }

    // إذا لم توجد تذاكر أو جميعها أكبر من m، فالجواب هو أصغر فرق مباشر
    if(tickets.empty()){
        cout << m << "\n"; // يمشي كل المسافة
        return 0;
    }

    // تقسيم القائمة إلى نصفين لتطبيق meet‑in‑the‑middle
    int sz = tickets.size();
    int mid = sz/2;
    vector<int64> left(tickets.begin(), tickets.begin()+mid);
    vector<int64> right(tickets.begin()+mid, tickets.end());

    vector<int64> sumsL, sumsR;
    // جميع مجموعات اليسار
    for(int mask=0; mask < (1<<left.size()); ++mask){
        int64 s = 0;
        for(int i=0;i<(int)left.size();++i) if(mask>>i & 1){
            if(s > INF64 - left[i]) { s = INF64; break; }
            s += left[i];
        }
        sumsL.push_back(s);
    }
    // جميع مجموعات اليمين
    for(int mask=0; mask < (1<<right.size()); ++mask){
        int64 s = 0;
        for(int i=0;i<(int)right.size();++i) if(mask>>i & 1){
            if(s > INF64 - right[i]) { s = INF64; break; }
            s += right[i];
        }
        sumsR.push_back(s);
    }
    sort(sumsR.begin(), sumsR.end());

    int64 best = m; // المشي الكامل كحد أقصى
    for(int64 sL : sumsL){
        // نريد sL + sR قريب من m
        int64 need = m - sL;
        // بحث ثنائي في sumsR
        auto it = lower_bound(sumsR.begin(), sumsR.end(), need);
        if(it != sumsR.end()) best = min(best, llabs(m - (sL + *it)));
        if(it != sumsR.begin()){
            --it;
            best = min(best, llabs(m - (sL + *it)));
        }
    }
    cout << best << "\n";
    return 0;
}
