    // dp_prev[i] = تكلفة تقسيم أول i عنصر إلى t‑1 مجموعة
    vector<int> dp_prev(N+1, INF), dp_cur(N+1, INF);
    dp_prev[0] = 0; // لا عناصر ولا مجموعات تكلفة صفر

    for(int t = 1; t <= K; ++t){
        int best = INF; // سيحفظ الحد الأدنى لـ dp_prev[p] - a[p]
        // نعيد تهيئة dp_cur لكل t جديد
        fill(dp_cur.begin(), dp_cur.end(), INF);
        for(int i = 1; i <= N; ++i){
