            // لأن المجموعة الحالية قد تبدأ من العنصر p+1
            best = min(best, dp_prev[i-1] - a[i-1]);
            dp_cur[i] = a[i-1] + best;
        }
        dp_prev.swap(dp_cur);
    }

    cout << dp_prev[N] << '\n';
    return 0;
}
