#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    vector<long long> sum; // مجموع القيم داخل كل مجموعة
    DSU(int n = 0) {init(n);}    
    void init(int n){
        parent.assign(n, -1);
        sum.assign(n, 0);
    }
    int find(int x){
        if(parent[x] < 0) return x;
        return parent[x] = find(parent[x]);
    }
    void unite(int a, int b, long long &best){
        a = find(a); b = find(b);
        if(a == b) return;
        // نجمع المجموعين ونحدّث القيمة القصوى
        if(parent[a] > parent[b]) swap(a, b); // a هو الأكبر (حجم سالب أصغر)
        parent[a] += parent[b];
        parent[b] = a;
        sum[a] += sum[b];
        if(sum[a] > best) best = sum[a];
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    if(!(cin >> N >> M)) return 0;
    vector<long long> w(N);
    for(int i = 0; i < N; ++i) cin >> w[i];
    vector<vector<int>> adj(N);
    for(int i = 0; i < M; ++i){
        int u, v; cin >> u >> v; --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    DSU dsu(N);
    vector<bool> active(N, false); // هل العقدة موجودة في الرسم الحالي
    vector<long long> answer(N);
    long long best = 0; // أكبر مجموع في الوقت الحالي

    // نضيف العقد بترتيب عكسي
    for(int day = N-1; day >= 0; --day){
        // قبل إضافة العقدة day تكون الإجابة هي best (وهي قيمة اليوم الذي يُفصل فيها هذه العقدة)
        answer[day] = best;
        // نضيف العقدة day إلى الرسم
        active[day] = true;
        dsu.sum[day] = w[day];
        if(w[day] > best) best = w[day];
        // ندمج مع جميع الجيران الذين تم إضافتهم مسبقاً
        for(int nb : adj[day]){
            if(active[nb]){
                dsu.unite(day, nb, best);
            }
        }
    }

    for(int i = 0; i < N; ++i){
        cout << answer[i] << '\n';
    }
    return 0;
}
