multiset<int>* dfs(int v){
    // إذا كان v ورقة
    if(g[v].empty()){
        auto *ms = new multiset<int>();
        ms->insert(0); // المسافة من الورقة إلى نفسها 0
        return ms;
    }
    // نختار أكبر مجموعة كقاعدة للدمج (small‑to‑large)
    multiset<int>* big = nullptr;
    for(int to: g[v]){
        auto *childSet = dfs(to);
        // رفع جميع المسافات في مجموعة الطفل بمقدار 1
        // نخلق مجموعة مؤقتة لتخزين القيم بعد الرفع لتفادي تعديل أثناء التكرار
        vector<int> tmp;
        tmp.reserve(childSet->size());
        for(int val: *childSet) tmp.push_back(val+1);
        childSet->clear();
        for(int val: tmp) childSet->insert(val);
        // دمج مع المجموعة الكبيرة
        if(!big){
            big = childSet;
        }else if(big->size() < childSet->size()){
            swap(big, childSet);
            for(int val: *childSet) big->insert(val);
            delete childSet;
        }else{
            for(int val: *childSet) big->insert(val);
            delete childSet;
        }
    }
    // الآن big تحتوي على كل مسافات الأوراق في شجرة v بعد رفع خطوة واحدة
    // نحذف القيم التي تتجاوز k
    while(!big->empty() && *big->rbegin() > k){
        // أكبر قيمة هي الأخيرة في multiset المرتب تصاعدياً
        auto it = prev(big->end());
        big->erase(it);
    }
    return big;
}

