public class Main {
    // تحويل حرف سداسي عشري إلى قيمة 0‑15
    private static int hexToInt(char c) {
        if (c >= '0' && c <= '9') return c - '0';
        return c - 'A' + 10; // الحروف الكبيرة فقط حسب بيان المسألة
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[][] a = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            int col = 0;
            for (int p = 0; p < line.length(); p++) {
                int val = hexToInt(line.charAt(p));
                // نكتب الأربعة بتات من الأكثر أهمية إلى الأقل
                for (int k = 3; k >= 0; k--) {
                    a[i][col++] = (val >> k) & 1;
                }
            }
        }

        // استخراج جميع القواسم ل n
        List<Integer> divisors = new ArrayList<>();
        for (int d = 1; d * d <= n; d++) {
            if (n % d == 0) {
                divisors.add(d);
                if (d != n / d) divisors.add(n / d);
            }
        }
        // نرتب القواسم تنازليًا للحصول على أكبر قيمة صالحة أولاً
        divisors.sort(Collections.reverseOrder());

        int answer = 1; // دائمًا x = 1 ممكن
        outer:
        for (int x : divisors) {
            // نتحقق من شرط التكرار للكتل بحجم x
            for (int i = 0; i < n; i++) {
                int ii = i % x;
                for (int j = 0; j < n; j++) {
                    if (a[i][j] != a[ii][j % x]) {
                        continue outer; // هذا القاسم غير صالح
                    }
                }
            }
            answer = x; // وجدنا أكبر قاسم صالح
            break;
        }

        System.out.println(answer);
    }
}
