                if (matrix[i][j-1] != matrix[i][j]) {
                    x = gcd(x, count);
                    count = 1;
                } else {
                    count++;
                }

            }
        }

        for (int i = 0; i < n; i++) {
            int count = 1;
            for (int j = 1; j < n; j++) {
