#include <bits/stdc++.h>
using namespace std;

// حساب عدد القمم التي يمكن الوصول إليها من "src" مع حظر المرور عبر "blocked"
static long long dfs_count(int src, int blocked, const vector<vector<int>>& g) {
    vector<char> visited(g.size(), 0);
    stack<int> st;
    st.push(src);
    visited[src] = 1;
    long long cnt = 0; // لا نعد src نفسه ولا blocked
    while (!st.empty()) {
        int v = st.top();
        st.pop();
        for (int to : g[v]) {
            if (to == blocked) continue;          // لا نسمح بالمرور عبر المدينة المحظورة
            if (!visited[to]) {
                visited[to] = 1;
                st.push(to);
                ++cnt; // كل عقدة نصل إليها هي جزء من المكوّن المطلوب
            }
        }
    }
    return cnt; // عدد القمم المستبعدة a و b تلقائيًا
}

