مسألة جديدة: احسب عدد أزواج المدن (x, y) بحيث أن أي مسار بينهما يمر عبر المدينتين a و b.
```cpp
#include <bits/stdc++.h>
using namespace std;

// دالة تقوم بعملية بحث (DFS) غير تعاودي وتعد عدد العقد التي يمكن الوصول إليها
// من المصدر src مع تجاهل العقدة المحظورة forbid.
long long countReachable(int src, int forbid, const vector<vector<int>>& g) {
    vector<char> visited(g.size(), 0);
    stack<int> st;
    st.push(src);
    visited[src] = 1;
    long long cnt = 0; // لا نعد العقدة src نفسها
    while (!st.empty()) {
        int u = st.top();
        st.pop();
        for (int v : g[u]) {
            if (v == forbid) continue;          // نتجنب المرور عبر العقدة المحظورة
            if (!visited[v]) {
                visited[v] = 1;
                st.push(v);
                ++cnt;                         // كل عقدة جديدة نصل إليها تُعدّ
            }
        }
    }
    return cnt; // عدد العقد التي يمكن الوصول إليها من src دون المرور بـ forbid
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; 
    if(!(cin >> T)) return 0;
    while (T--) {
        int n, m, a, b;
        cin >> n >> m >> a >> b;
        vector<vector<int>> g(n + 1);
        for (int i = 0; i < m; ++i) {
            int u, v; cin >> u >> v;
            g[u].push_back(v);
            g[v].push_back(u);
        }
        // عدد المدن التي يمكن الوصول إليها من a دون المرور بـ b (مع استبعاد a نفسها)
        long long cntA = countReachable(a, b, g);
        // عدد المدن التي يمكن الوصول إليها من b دون المرور بـ a (مع استبعاد b نفسها)
        long long cntB = countReachable(b, a, g);
        // الإجابة هي حاصل ضرب العددين
        cout << cntA * cntB << '\n';
    }
    return 0;
}
```
