  memset(idxB, -1, sizeof(idxB));
  for (int j = 0, _n = (lenB); j < _n; ++j) {
    scanf("%d", B + j);
    idxB[B[j]] = j;
  }
  int idxV = 0;
  vector<long long> V;
  long long offset = 0;
  int res = 0;
  for (int k = 0, _n = (lenA * 2); k < _n; ++k) {
    long long p = idxB[A[k % lenA]];
    if (p < 0) {
      V.clear();
      idxV = 0;
      continue;
    }
    p += offset;
    if (!V.empty() && V.back() >= p) {
      p += lenB;
      offset += lenB;
    }
    V.push_back(p);
    idxV = (lower_bound(V.begin() + idxV, V.end(), p - lenB + 1) - V.begin());
    int len = int((V).size()) - idxV;
    res = max(res, len);
  }
